language sql
immutable
set search_path = ''
as $fn$
  select $edital$[{"nome":"Língua Portuguesa","grupo":"Básicos · Língua Portuguesa (10 questões)","antigos":[],"topicos":["Gênero do texto: literário e não literário, narrativo, descritivo e argumentativo","Interpretação e organização interna do texto","Semântica: sentido e emprego dos vocábulos e campos semânticos","Emprego de tempos e modos dos verbos","Classes gramaticais: reconhecimento, emprego e sentido","Processos de formação de palavras","Flexão dos nomes e dos verbos","Frase, oração e período","Termos da oração","Coordenação e subordinação","Concordância verbal e nominal","Transitividade e regência de nomes e verbos","Colocação pronominal","Mecanismos de coesão textual","Ortografia","Acentuação gráfica","Emprego do sinal indicativo de crase","Pontuação","Reescrita de frases: substituição, deslocamento e paralelismo","Variação linguística: norma culta"]},{"nome":"Ética no Serviço Público","grupo":"Básicos · Ética, Regimento, LOJ e Provimentos (10 questões no total)","antigos":[],"topicos":["Ética e moral","Ética, princípios e valores","Ética e democracia: exercício da cidadania","Ética e função pública","Ética no setor público","Lei 8.112/1990: regime disciplinar","Lei 8.112/1990: deveres e proibições","Lei 8.112/1990: acumulação de cargos","Lei 8.112/1990: responsabilidades e penalidades","Lei 8.429/1992 (improbidade): disposições gerais","Lei 8.429/1992: atos de improbidade administrativa","Código de Ética dos Servidores do TJDFT (Resolução 9/2019 e Portaria Conjunta 76/2020)"]},{"nome":"Regimento Interno do TJDFT","grupo":"Básicos · Ética, Regimento, LOJ e Provimentos (10 questões no total)","antigos":[],"topicos":["Disposições iniciais e composição do Tribunal","Tribunal Pleno, Conselho Especial e Conselho da Magistratura","Câmaras e Turmas","Presidência, Vice-Presidências e Corregedoria","Comissões permanentes e temporárias","Eleições, posse e substituições","Registro, distribuição e prevenção","Preparo e deserção","Sessões, pauta e julgamento","Process