ates, quesitos e votação, sentença, ata e atribuições do presidente","Prisão e liberdade provisória","Crimes de responsabilidade dos funcionários públicos: processo e julgamento","Habeas corpus e seu processo","Disposições constitucionais aplicáveis ao processo penal"]},{"nome":"Redação (prova discursiva)","grupo":"Prova discursiva · Redação (30 pontos)","antigos":[],"topicos":["Gênero dissertativo-argumentativo (15 a 20 linhas)","Tema, tese e abordagem","Argumentação e repertório","Progressão textual: coesão e coerência entre parágrafos","Seleção vocabular e norma culta","Critérios de correção e penalidades do edital"]}]$edital$::jsonb
$fn$;

-- ---------------------------------------------------------------------------
-- Revisão 1 do edital nas contas que já existem
-- ---------------------------------------------------------------------------

create or replace function public.revisar_edital_2022()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  renomeados jsonb := $renomeados$[{"materia":"Noções de Administração de Recursos Humanos e Gestão Pública","de":"Eficiência, eficácia e efetividade e avaliação do desempenho governamental","para":"Eficácia e efetividade: avaliação e mensuração do desempenho governamental"}]$renomeados$::jsonb;
  r jsonb;
  m jsonb;
  m_id uuid;
  nomes text[];
begin
  if uid is null then
    raise exception 'É preciso estar logada para revisar o edital.';
  end if;

  insert into public.configuracoes (user_id) values (uid) on conflict (user_id) do nothing;
  if (select edital_revisao from public.configuracoes where user_id = uid) >= 1 then
    return;
  end if;

  -- Renomeia no lugar, para o tópico manter tudo o que já está ligado a ele.
  for r in select * from jsonb_array_elements(renomeados) loop
    update public.topicos t
    set nome = r ->> 'para'
    from public.materias mt
    where mt.id = t.materia_id
      and mt.user_id = uid
      and mt.nome = r ->> 'materia'
      and t.nome = r ->> 'de'
      and not exists (select 1 from public.topicos t2 where t2.materia_id = mt.id and t2.nome = r ->> 'para');
  end loop;

  for m in select * from jsonb_array_elements(public.edital_tjdft_2022()) loop
    m_id := null;
    select id into m_id from public.materias where user_id = uid and nome = m ->> 'nome' limit 1;
    continue when m_id is null;

    nomes := array(select jsonb_array_elements_text(m -> 'topicos'));

    insert into public.topicos (user_id, materia_id, nome, ordem)
    select uid, m_id, x.nome, (x.ordem - 1)::integer
    from unnest(nomes) with ordinality as x (nome, ordem)
    where not exists (select 1 from public.topicos t where t.materia_id = m_id and t.nome = x.nome);

    -- Ordem do edital primeiro; tópicos criados por você continuam, no fim.
    update public.topicos t
    set ordem = coalesce(array_position(nomes, t.nome) - 1, 1000 + t.ordem)
    where t.materia_id = m_id
      and (array_position(nomes, t.nome) is not null or t.ordem < 1000);
  end loop;

  update public.configuracoes set edital_revisao = 1 where user_id = uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- Nomenclatura: segunda leva de termos
-- ---------------------------------------------------------------------------

create or replace function public.semear_termos_2022b()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  termos jsonb := $termos$[{"termo":"Frase, oração e período","extenso":"Unidades da sintaxe","pratica":"Frase é qualquer enunciado com sentido; oração é o trecho organizado em torno de um verbo; período é a frase formada por uma ou mais orações.","tecnica":"Período simples tem uma oração (absoluta); período composto tem duas ou mais. Conte os verbos (locução verbal conta como um) para saber quantas orações há.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Frase, oração e período"]]},{"termo":"Frase nominal","extenso":"Frase sem verbo","pratica":"Frase que comunica sem ter verbo: “Silêncio!”, “Fogo!”.","tecnica":"Não é oração, porque não tem verbo. A banca usa para separar o conceito de frase do de oração.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Frase, oração e período"]]},{"termo":"Sujeito oculto","extenso":"Sujeito desinencial","pratica":"O sujeito não aparece escrito, mas a terminação do verbo mostra quem é: “Saímos cedo” (nós).","tecnica":"Identificado pela desinência verbal ou pelo contexto. Não confundir com sujeito indeterminado, em que não se sabe quem pratica a ação.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Sujeito indeterminado","extenso":"Sujeito que não se identifica","pratica":"Alguém pratica a ação, mas o texto não diz quem: “Roubaram meu carro”.","tecnica":"Ocorre com verbo na 3ª pessoa do plural sem referente ou com verbo intransitivo, transitivo indireto ou de ligação + “se” (índice de indeterminação do sujeito), com o verbo no singular.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Predicativo do sujeito","extenso":"Qualidade atribuída ao sujeito","pratica":"Característica ou estado do sujeito ligado a ele pelo verbo: “O servidor está cansado”.","tecnica":"Aparece com verbo de ligação (predicado nominal) ou junto a verbo significativo (predicado verbo-nominal: “O réu saiu calado”).","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Verbo de ligação","extenso":"Verbo que liga sujeito e predicativo","pratica":"Verbo que não indica ação, só liga o sujeito a uma qualidade: ser, estar, parecer, permanecer, ficar, continuar.","tecnica":"A classificação depende do contexto: em “Ele ficou em casa” o verbo é intransitivo (com adjunto de lugar); em “Ele ficou triste”, é de ligação.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"],["Língua Portuguesa","Classes gramaticais: reconhecimento, emprego e sentido"]]},{"termo":"Complemento nominal","extenso":"Complemento de um nome","pratica":"Termo com preposição que completa o sentido de um substantivo, adjetivo ou advérbio: “necessidade de descanso”.","tecnica":"Paciente da ideia do nome (“a defesa do réu” = alguém defende o réu). Se for agente ou possuidor, é adjunto adnominal (“a defesa do advogado”).","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Adjunto adnominal","extenso":"Termo que acompanha o substantivo","pratica":"Palavra que acompanha o substantivo para determinar ou caracterizar: artigos, adjetivos, pronomes, numerais, locuções.","tecnica":"Com preposição, é agente ou posse (“o voto do relator”); contrasta com o complemento nominal, que é paciente.","dispositivo":null,"tags":["sintaxe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Aposto","extenso":"Termo que explica outro","pratica":"Trecho que explica ou resume um termo anterior, quase sempre entre vírgulas: “Brasília, capital do país, ...”.","tecnica":"Aposto explicativo vem entre vírgulas, travessões ou parênteses; o especificativo não leva vírgula (“o rio Paranoá”). Retirar o aposto não prejudica a correção.","dispositivo":null,"tags":["sintaxe","vírgula"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"],["Língua Portuguesa","Pontuação"]]},{"termo":"Vocativo","extenso":"Chamamento","pratica":"Termo usado para chamar ou interpelar alguém: “Senhor Presidente, ...”.","tecnica":"É isolado por vírgula e não pertence à estrutura da oração. Na redação oficial, o vocativo do ofício é “Senhor + cargo”, seguido de vírgula.","dispositivo":null,"tags":["sintaxe","vírgula"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"],["Língua Portuguesa","Pontuação"]]},{"termo":"Agente da passiva","extenso":"Quem pratica a ação na voz passiva","pratica":"Na voz passiva, é quem faz a ação, introduzido por “por” ou “pelo”: “A sentença foi proferida pelo juiz”.","tecnica":"Só existe na voz passiva analítica. Na transposição para a ativa, o agente vira sujeito.","dispositivo":null,"tags":["sintaxe","vozes verbais"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Termos da oração"]]},{"termo":"Oração subordinada substantiva","extenso":"Oração com valor de substantivo","pratica":"Oração que faz o papel de sujeito, objeto ou complemento de outra: “É necessário que todos compareçam”.","tecnica":"Geralmente iniciada pela conjunção integrante “que” ou “se”. Pode ser trocada por “isso”: “É necessário isso”.","dispositivo":null,"tags":["sintaxe","períodos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Oração subordinada adverbial","extenso":"Oração com valor de advérbio","pratica":"Oração que indica circunstância (causa, condição, concessão, tempo, finalidade, consequência...) em relação à principal.","tecnica":"A banca troca a conjunção e pergunta se o sentido se mantém: “embora” (concessão) ≠ “porque” (causa); “caso/se” (condição); “para que” (finalidade).","dispositivo":null,"tags":["sintaxe","conectivos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Oração reduzida","extenso":"Oração sem conectivo e com verbo no infinitivo, gerúndio ou particípio","pratica":"Oração “encurtada”: “Terminado o prazo, o processo foi arquivado” (= quando o prazo terminou).","tecnica":"Reescrever a reduzida em desenvolvida (com conectivo e verbo flexionado) é questão clássica de reescrita: mantenha o mesmo valor circunstancial.","dispositivo":null,"tags":["sintaxe","reescrita"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"],["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"]]},{"termo":"Conjunção conclusiva","extenso":"Conectivo de conclusão","pratica":"Liga a ideia final a partir do que veio antes: logo, portanto, por isso, pois (depois do verbo).","tecnica":"“Pois” é conclusivo quando vem posposto ao verbo e entre vírgulas (“Estudou; passará, pois, na prova”) e explicativo quando anteposto.","dispositivo":null,"tags":["conectivos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Conjunção explicativa","extenso":"Conectivo de explicação","pratica":"Justifica o que se disse antes: pois (anteposto), porque, que.","tecnica":"Explicação ≠ causa: a explicativa justifica uma afirmação ou ordem (“Volte, que vai chover”); a causal liga causa e efeito dentro da subordinação.","dispositivo":null,"tags":["conectivos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Coordenação e subordinação"]]},{"termo":"Pronome relativo","extenso":"Pronome que retoma um termo e inicia oração","pratica":"Palavra que retoma um termo anterior e abre uma oração: que, o qual, cujo, onde, quem, quanto.","tecnica":"“Cujo” indica posse e não leva artigo depois (“cujo processo”, nunca “cujo o”). “Onde” só para lugar físico. A preposição exigida pelo verbo vem antes do relativo (“em que”, “de que”).","dispositivo":null,"tags":["coesão","pronomes"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Classes gramaticais: reconhecimento, emprego e sentido"],["Língua Portuguesa","Mecanismos de coesão textual"]]},{"termo":"Preposição","extenso":"Palavra que liga termos","pratica":"Palavra invariável que liga dois termos estabelecendo relação: a, ante, até, com, contra, de, desde, em, entre, para, por, sem, sob, sobre, trás.","tecnica":"Na crase, a preposição “a” se funde com o artigo “a”. Em regência, a preposição exigida pelo verbo ou nome não pode ser omitida.","dispositivo":null,"tags":["classes"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Classes gramaticais: reconhecimento, emprego e sentido"],["Língua Portuguesa","Transitividade e regência de nomes e verbos"]]},{"termo":"Advérbio","extenso":"Palavra que indica circunstância","pratica":"Modifica verbo, adjetivo ou outro advérbio indicando tempo, lugar, modo, intensidade, negação etc.","tecnica":"Advérbio deslocado para o início da oração pode ser isolado por vírgula (facultativa se curto). “Não” atrai o pronome oblíquo (próclise).","dispositivo":null,"tags":["classes"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Classes gramaticais: reconhecimento, emprego e sentido"]]},{"termo":"Infinitivo pessoal","extenso":"Infinitivo flexionado","pratica":"Infinitivo que concorda com o sujeito: “É hora de vocês saírem”.","tecnica":"Flexiona-se quando tem sujeito próprio diferente do da oração principal ou para dar clareza; em locuções verbais não se flexiona (“Devem sair”).","dispositivo":null,"tags":["verbos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Flexão dos nomes e dos verbos"],["Língua Portuguesa","Emprego de tempos e modos dos verbos"]]},{"termo":"Futuro do pretérito","extenso":"Tempo verbal do condicional","pratica":"Indica fato que ocorreria sob condição ou expressa hipótese e polidez: “Seria possível ajudar?”.","tecnica":"Em textos jornalísticos e jurídicos indica informação não confirmada (“o réu teria fugido”). Substituí-lo por presente muda o grau de certeza.","dispositivo":null,"tags":["verbos"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Emprego de tempos e modos dos verbos"]]},{"termo":"Hiperônimo","extenso":"Palavra de sentido mais amplo","pratica":"Termo geral que abrange outros: “veículo” é hiperônimo de “carro”; “carro” é hipônimo de “veículo”.","tecnica":"Usado como mecanismo de coesão por substituição: retomar “juiz” por “magistrado” ou “autoridade”. A banca pergunta se a retomada mantém a referência.","dispositivo":null,"tags":["coesão","semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"],["Língua Portuguesa","Mecanismos de coesão textual"]]},{"termo":"Sinonímia","extenso":"Relação entre palavras de sentido próximo","pratica":"Palavras com sentido parecido no contexto: “findar” e “terminar”.","tecnica":"Sinônimo perfeito é raro: a banca avalia se a troca mantém o sentido no contexto específico, inclusive a regência.","dispositivo":null,"tags":["semântica"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"],["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"]]},{"termo":"Ambiguidade","extenso":"Duplo sentido","pratica":"Frase que pode ser entendida de duas formas: “Vi o incêndio do prédio” (eu estava no prédio ou vi o prédio pegar fogo?).","tecnica":"Causas comuns: posição de termos, pronome possessivo “seu”, relativo com dois antecedentes. FGV 2022 (q. 6) pediu a frase com ambiguidade possível.","dispositivo":null,"tags":["semântica","FGV"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"],["Língua Portuguesa","Interpretação e organização interna do texto"]]},{"termo":"Metáfora","extenso":"Comparação implícita","pratica":"Uso de uma palavra com sentido figurado por semelhança, sem conectivo: “Aquele juiz é uma rocha”.","tecnica":"Comparação usa conectivo (“como”); metáfora não. Em interpretação, a banca pede o sentido figurado no contexto.","dispositivo":null,"tags":["figuras de linguagem"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"]]},{"termo":"Metonímia","extenso":"Troca por relação de proximidade","pratica":"Troca de um termo por outro com que mantém relação lógica: “Li Machado” (a obra pelo autor), “O Planalto decidiu” (o governo pelo prédio).","tecnica":"Diferente da metáfora: não há semelhança, há contiguidade (autor/obra, lugar/instituição, parte/todo).","dispositivo":null,"tags":["figuras de linguagem"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Semântica: sentido e emprego dos vocábulos e campos semânticos"]]},{"termo":"Inferência","extenso":"Conclusão a partir do texto","pratica":"Ideia que não está escrita, mas pode ser deduzida com segurança do que o texto diz.","tecnica":"Itens de “infere-se” exigem apoio no texto; extrapolação (ir além do texto) e redução (ficar aquém) tornam o item errado.","dispositivo":null,"tags":["interpretação","Cebraspe"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Interpretação e organização interna do texto"]]},{"termo":"Pressuposto","extenso":"Informação implícita garantida por marca linguística","pratica":"Ideia que a própria frase carrega: “Ele parou de fumar” pressupõe que fumava.","tecnica":"Pressuposto vem de palavras (verbos como parar/continuar, advérbios como ainda/já); subentendido depende do contexto e de quem lê.","dispositivo":null,"tags":["interpretação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Interpretação e organização interna do texto"]]},{"termo":"Parassíntese","extenso":"Formação com prefixo e sufixo ao mesmo tempo","pratica":"Palavra criada com prefixo e sufixo juntos, sem existir só com um deles: “entardecer”, “emagrecer”.","tecnica":"Diferente da derivação prefixal e sufixal, em que a palavra existe com cada afixo separadamente (“infelizmente”).","dispositivo":null,"tags":["formação de palavras"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Processos de formação de palavras"]]},{"termo":"Neologismo","extenso":"Palavra nova","pratica":"Palavra criada ou adaptada recentemente: “deletar”, “cibercrime”.","tecnica":"Pode surgir por derivação, composição ou empréstimo. Estrangeirismos aparecem em itálico nos textos da banca.","dispositivo":null,"tags":["formação de palavras"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Processos de formação de palavras"],["Língua Portuguesa","Variação linguística: norma culta"]]},{"termo":"Hífen","extenso":"Regras do hífen (Acordo de 1990)","pratica":"Traço que liga elementos de palavras compostas ou prefixos: “anti-inflamatório”, “micro-ondas”.","tecnica":"Com prefixo: há hífen quando o segundo elemento começa com h ou com a mesma vogal do prefixo (“anti-higiênico”, “micro-ondas”); sem hífen quando as vogais são diferentes (“autoestima”); r e s dobram (“antirrábico”).","dispositivo":null,"tags":["ortografia"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Ortografia"]]},{"termo":"Porquês","extenso":"Por que, porque, por quê, porquê","pratica":"Por que: pergunta ou “pelo qual”; porque: explicação/causa; por quê: no fim da frase; porquê: substantivo (“o porquê”).","tecnica":"“Por que” também equivale a “pelo(a) qual” (“o caminho por que passei”). “Porquê” vem com artigo ou determinante.","dispositivo":null,"tags":["ortografia"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Ortografia"]]},{"termo":"Proparoxítona","extenso":"Palavra com acento na antepenúltima sílaba","pratica":"Todas as proparoxítonas são acentuadas: “lâmpada”, “jurídico”, “período”.","tecnica":"Inclui as aparentes (terminadas em ditongo crescente: “história”, “série”), que também levam acento.","dispositivo":null,"tags":["acentuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Acentuação gráfica"]]},{"termo":"Acento diferencial","extenso":"Acento que distingue palavras","pratica":"Acento que diferencia palavras de mesma grafia: “pôr” (verbo) × “por” (preposição); “pôde” (passado) × “pode” (presente).","tecnica":"Após o Acordo de 1990, caiu em “para”, “pelo”, “polo”, “pera”. Mantém-se em têm/vêm (plural) e é facultativo em “fôrma”.","dispositivo":null,"tags":["acentuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Acentuação gráfica"]]},{"termo":"Crase facultativa","extenso":"Casos em que a crase é opcional","pratica":"Antes de pronome possessivo feminino (“à/a minha casa”), nomes próprios femininos (“à/a Maria”) e depois de “até” (“até à/a porta”).","tecnica":"Nesses casos a presença do artigo é opcional, por isso o acento também. Questões perguntam se a retirada do acento prejudica a correção: aqui não prejudica.","dispositivo":null,"tags":["crase"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Emprego do sinal indicativo de crase"]]},{"termo":"Vírgula proibida","extenso":"Vírgula entre termos essenciais","pratica":"Não se separa com vírgula sujeito de verbo, verbo de complemento nem nome de complemento nominal.","tecnica":"Exceção aparente: se houver termo intercalado, ele vem entre duas vírgulas (“O juiz, de ofício, decidiu”). Uma vírgula sozinha entre sujeito e verbo é erro.","dispositivo":null,"tags":["vírgula"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Pontuação"]]},{"termo":"Ponto e vírgula","extenso":"Pausa maior que a vírgula","pratica":"Separa orações coordenadas longas, itens de enumeração e orações com conjunção deslocada (“O prazo venceu; o recurso, portanto, é intempestivo”).","tecnica":"Pode substituir o ponto entre orações relacionadas. Em itens de lei e enumerações, separa incisos.","dispositivo":null,"tags":["pontuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Pontuação"]]},{"termo":"Travessão","extenso":"Sinal de pontuação de destaque","pratica":"Destaca explicações ou mudanças de interlocutor; o duplo pode substituir vírgulas ou parênteses.","tecnica":"O travessão duplo isola intercalações (como no aposto). Na reescrita, trocar travessões por vírgulas costuma manter a correção.","dispositivo":null,"tags":["pontuação"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Pontuação"]]},{"termo":"Dois-pontos","extenso":"Sinal que anuncia","pratica":"Introduz enumeração, explicação, citação ou consequência: “Ela tem todos os poderes: a beleza, a justiça...”.","tecnica":"FGV 2022 (q. 2): a segunda parte depois dos dois-pontos fazia enumeração. A banca pergunta o valor do que vem depois.","dispositivo":null,"tags":["pontuação","FGV"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Pontuação"]]},{"termo":"Discurso direto e indireto","extenso":"Formas de reproduzir falas","pratica":"Direto: a fala aparece como foi dita, com aspas ou travessão. Indireto: o narrador conta o que foi dito, com “que” ou “se”.","tecnica":"Na passagem do direto para o indireto mudam pessoa, tempo verbal (presente → pretérito imperfeito) e advérbios (hoje → naquele dia).","dispositivo":null,"tags":["reescrita"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Reescrita de frases: substituição, deslocamento e paralelismo"]]},{"termo":"Elipse","extenso":"Omissão de termo identificável","pratica":"Omissão de um termo fácil de recuperar: “No tribunal, silêncio” (há silêncio).","tecnica":"Zeugma é a elipse de termo já mencionado (“Eu prefiro o recurso; ela, a ação”). Ambas são mecanismos de coesão.","dispositivo":null,"tags":["coesão"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Mecanismos de coesão textual"]]},{"termo":"Haver impessoal","extenso":"Verbo haver no sentido de existir","pratica":"Com sentido de existir ou de tempo decorrido, “haver” fica no singular: “Havia muitos processos”, “Há anos não o vejo”.","tecnica":"Em locução, o auxiliar também fica no singular: “Deve haver erros”. Trocar por “existir” obriga a concordar (“Existiam muitos processos”).","dispositivo":null,"tags":["concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Concordância verbal e nominal"]]},{"termo":"Silepse","extenso":"Concordância com a ideia","pratica":"Concordância feita com o sentido, não com a forma: “A gente fomos” (popular), “Os brasileiros somos otimistas” (de pessoa).","tecnica":"Silepse de pessoa e de número aparecem em textos literários; em norma-padrão, a banca avalia se o desvio é aceitável no contexto.","dispositivo":null,"tags":["concordância"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Concordância verbal e nominal"],["Língua Portuguesa","Variação linguística: norma culta"]]},{"termo":"Assistir (regência)","extenso":"Regência do verbo assistir","pratica":"No sentido de ver, pede “a”: “assistir ao jogo”. No sentido de ajudar, é direto: “o advogado assiste o réu”.","tecnica":"No sentido de “caber, pertencer”, também pede “a”: “Assiste ao réu o direito de calar”. Com “a” + palavra feminina, há crase.","dispositivo":null,"tags":["regência"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Transitividade e regência de nomes e verbos"],["Língua Portuguesa","Emprego do sinal indicativo de crase"]]},{"termo":"Implicar (regência)","extenso":"Regência do verbo implicar","pratica":"No sentido de acarretar, é transitivo direto: “A decisão implica mudanças” (nunca “implica em”).","tecnica":"No sentido de “antipatizar”, pede “com”: “implicar com alguém”. A banca cobra a forma culta sem preposição.","dispositivo":null,"tags":["regência"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Transitividade e regência de nomes e verbos"]]},{"termo":"Registro formal e informal","extenso":"Níveis de linguagem","pratica":"Formal é a linguagem cuidada (documentos, provas); informal é a do dia a dia, com gírias e contrações.","tecnica":"Adequação linguística: a banca avalia se a variante é adequada à situação, não se é “certa” em absoluto. Em redação de prova exige-se a norma-padrão.","dispositivo":null,"tags":["variação"],"materias":["Língua Portuguesa","Redação (prova discursiva)"],"topicos":[["Língua Portuguesa","Variação linguística: norma culta"],["Redação (prova discursiva)","Seleção vocabular e norma culta"]]},{"termo":"Texto narrativo","extenso":"Tipo textual que conta fatos","pratica":"Relata acontecimentos em sequência, com personagens, tempo e espaço.","tecnica":"Marcas: verbos de ação no pretérito, marcadores temporais, narrador. Pode aparecer como base de argumentação em textos dissertativos.","dispositivo":null,"tags":["tipos textuais"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Gênero do texto: literário e não literário, narrativo, descritivo e argumentativo"]]},{"termo":"Texto descritivo","extenso":"Tipo textual que caracteriza","pratica":"Mostra como algo é: características de pessoas, objetos, lugares.","tecnica":"Predominam adjetivos, verbos de estado e enumeração. Raramente aparece puro; costuma estar dentro de narrações.","dispositivo":null,"tags":["tipos textuais"],"materias":["Língua Portuguesa"],"topicos":[["Língua Portuguesa","Gênero do texto: literário e não literário, narrativo, descritivo e argumentativo"]]},{"termo":"Introdução","extenso":"Primeiro parágrafo da dissertação","pratica":"Apresenta o tema e a tese, ou seja, o ponto de vista que o texto vai defender.","tecnica":"Deve situar o leitor sem detalhar argumentos. Em 15 a 20 linhas, de 3 a 4 linhas bastam.","dispositivo":null,"tags":["estrutura"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Gênero dissertativo-argumentativo (15 a 20 linhas)"],["Redação (prova discursiva)","Tema, tese e abordagem"]]},{"termo":"Parágrafo de desenvolvimento","extenso":"Corpo da dissertação","pratica":"Cada parágrafo de desenvolvimento defende um argumento que sustenta a tese.","tecnica":"Estrutura útil: tópico frasal + fundamentação (dado, exemplo, lei) + fechamento ligado à tese.","dispositivo":null,"tags":["estrutura"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Gênero dissertativo-argumentativo (15 a 20 linhas)"],["Redação (prova discursiva)","Argumentação e repertório"]]},{"termo":"Conclusão","extenso":"Último parágrafo da dissertação","pratica":"Retoma a tese e fecha o raciocínio; não traz argumento novo.","tecnica":"Pode sintetizar ou propor encaminhamento. Na FGV não se exige proposta de intervenção, mas o fechamento precisa responder às perguntas do tema.","dispositivo":null,"tags":["estrutura"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Gênero dissertativo-argumentativo (15 a 20 linhas)"]]},{"termo":"Tópico frasal","extenso":"Frase-núcleo do parágrafo","pratica":"Primeira frase do parágrafo, que anuncia a ideia que ele vai desenvolver.","tecnica":"Ajuda a progressão: cada parágrafo traz uma ideia nova ligada à tese, sem repetir a anterior.","dispositivo":null,"tags":["estrutura"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Progressão textual: coesão e coerência entre parágrafos"]]},{"termo":"Repertório","extenso":"Conhecimento de mundo usado como prova","pratica":"Dados, leis, fatos históricos ou exemplos usados para sustentar os argumentos.","tecnica":"Precisa ser pertinente e explicado. Citar algo sem ligar ao argumento não conta como argumentação.","dispositivo":null,"tags":["argumentação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Argumentação e repertório"]]},{"termo":"Argumento de autoridade","extenso":"Apoio em fonte reconhecida","pratica":"Uso da opinião de especialista, lei ou instituição para dar força ao que se defende.","tecnica":"Não substitui o raciocínio próprio: depois da citação, explique como ela confirma a tese.","dispositivo":null,"tags":["argumentação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Argumentação e repertório"]]},{"termo":"Argumento por exemplificação","extenso":"Apoio em exemplos","pratica":"Uso de casos concretos para ilustrar a ideia defendida.","tecnica":"Um bom exemplo é específico e representativo; exemplos genéricos (“muitas pessoas acham”) enfraquecem o texto.","dispositivo":null,"tags":["argumentação"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Argumentação e repertório"]]},{"termo":"Causa e consequência","extenso":"Argumento de relação causal","pratica":"Mostra por que um fato acontece e quais efeitos produz.","tecnica":"Conectivos úteis: porque, visto que, uma vez que (causa); por isso, consequentemente, de modo que (consequência).","dispositivo":null,"tags":["argumentação","conectivos"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Argumentação e repertório"],["Redação (prova discursiva)","Progressão textual: coesão e coerência entre parágrafos"]]},{"termo":"Tangenciamento do tema","extenso":"Abordagem parcial do tema","pratica":"Escrever sobre o assunto geral sem responder exatamente ao que o tema pede.","tecnica":"Penaliza bastante a nota de conteúdo. Ex.: tema sobre o futuro dos jornais impressos e texto só sobre a Internet.","dispositivo":null,"tags":["tema"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Tema, tese e abordagem"],["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Impessoalidade na redação","extenso":"Texto em 3ª pessoa","pratica":"Preferência por construções impessoais, sem “eu acho” ou apelos ao leitor.","tecnica":"Em dissertação de concurso, a primeira pessoa costuma ser desaconselhada; marcas de opinião vêm de verbos e adjetivos avaliativos, não de “eu”.","dispositivo":null,"tags":["estilo"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Seleção vocabular e norma culta"]]},{"termo":"Limite de linhas","extenso":"Extensão mínima e máxima","pratica":"A redação de Técnico do TJDFT 2022 pedia de 15 a 20 linhas.","tecnica":"Texto abaixo do mínimo pode ser zerado ou penalizado; linhas além do máximo são desconsideradas. Confira as regras no edital.","dispositivo":null,"tags":["regras"],"materias":["Redação (prova discursiva)"],"topicos":[["Redação (prova discursiva)","Critérios de correção e penalidades do edital"]]},{"termo":"Deontologia","extenso":"Estudo dos deveres","pratica":"Parte da ética que trata dos deveres de uma profissão ou função.","tecnica":"Códigos de ética profissionais são deontológicos: listam deveres, vedações e regras de conduta.","dispositivo":null,"tags":["ética"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e moral"],["Ética no Serviço Público","Código de Ética dos Servidores do TJDFT (Resolução 9/2019 e Portaria Conjunta 76/2020)"]]},{"termo":"Probidade","extenso":"Honestidade no exercício da função","pratica":"Agir com honestidade e lealdade à administração.","tecnica":"A falta de probidade dá base à improbidade administrativa (Lei 8.429/1992). Cebraspe 2013 cobrou probidade como fator de legitimidade dos atos do servidor.","dispositivo":null,"tags":["ética","Cebraspe"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética no setor público"],["Ética no Serviço Público","Ética e função pública"]]},{"termo":"Moralidade administrativa","extenso":"Princípio da moralidade","pratica":"Além de legal, o ato precisa ser honesto e de boa-fé.","tecnica":"Princípio expresso do art. 37 da CF. Atos imorais podem ser anulados, por exemplo, por ação popular.","dispositivo":"CF, art. 37, caput","tags":["princípios"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Ética e função pública"],["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"]]},{"termo":"Controle social","extenso":"Fiscalização do Estado pela sociedade","pratica":"Participação do cidadão no acompanhamento e na cobrança da administração pública.","tecnica":"Instrumentos: acesso à informação, audiências públicas, conselhos, ouvidorias, ação popular.","dispositivo":null,"tags":["cidadania"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e democracia: exercício da cidadania"]]},{"termo":"LAI","extenso":"Lei de Acesso à Informação","pratica":"Lei que garante a qualquer pessoa o direito de pedir informações públicas, sem precisar dizer por quê.","tecnica":"Publicidade é a regra e o sigilo, a exceção. Transparência ativa (divulgar sem pedido) e passiva (responder pedidos).","dispositivo":"Lei 12.527/2011","tags":["transparência"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e democracia: exercício da cidadania"],["Ética no Serviço Público","Ética no setor público"]]},{"termo":"Conflito de interesses","extenso":"Choque entre interesse público e privado","pratica":"Situação em que o interesse pessoal do servidor pode influenciar sua atuação pública.","tecnica":"No Executivo federal é regulado pela Lei 12.813/2013. Códigos de ética exigem que o servidor se declare impedido ou suspeito.","dispositivo":null,"tags":["ética"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética e função pública"]]},{"termo":"Nepotismo","extenso":"Favorecimento de parentes","pratica":"Nomear parente para cargo em comissão ou função de confiança por causa do parentesco.","tecnica":"Súmula Vinculante 13 proíbe nomeação de cônjuge, companheiro ou parente até o 3º grau da autoridade nomeante ou de servidor em cargo de direção, inclusive por designações recíprocas.","dispositivo":"Súmula Vinculante 13","tags":["moralidade"],"materias":["Ética no Serviço Público","Noções de Direito Constitucional"],"topicos":[["Ética no Serviço Público","Ética e função pública"],["Noções de Direito Constitucional","Administração pública: disposições gerais"]]},{"termo":"Assédio moral","extenso":"Conduta abusiva repetida no trabalho","pratica":"Humilhações, isolamento ou exposição repetidos que degradam o ambiente de trabalho.","tecnica":"Pode configurar infração ética e disciplinar. Códigos de ética de tribunais vedam esse tipo de conduta.","dispositivo":null,"tags":["conduta"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Ética no setor público"],["Ética no Serviço Público","Código de Ética dos Servidores do TJDFT (Resolução 9/2019 e Portaria Conjunta 76/2020)"]]},{"termo":"Conversão da suspensão em multa","extenso":"Suspensão substituída por multa","pratica":"Por conveniência do serviço, a suspensão pode virar multa: o servidor continua trabalhando e perde parte da remuneração.","tecnica":"Multa de 50% por dia de vencimento ou remuneração, ficando o servidor obrigado a permanecer em serviço.","dispositivo":"Lei 8.112/1990, art. 130, § 2º","tags":["Lei 8.112","penalidades"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"],["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Afastamento preventivo","extenso":"Afastamento do servidor durante o PAD","pratica":"Para não atrapalhar a apuração, o servidor pode ser afastado do cargo.","tecnica":"Até 60 dias, prorrogável por igual prazo, sem prejuízo da remuneração.","dispositivo":"Lei 8.112/1990, art. 147","tags":["PAD"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Comissão do PAD","extenso":"Comissão que conduz o processo disciplinar","pratica":"Grupo de servidores que investiga e relata o processo disciplinar.","tecnica":"Três servidores estáveis designados pela autoridade; o presidente deve ocupar cargo efetivo superior ou de mesmo nível, ou ter escolaridade igual ou superior à do indiciado.","dispositivo":"Lei 8.112/1990, art. 149","tags":["PAD"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Prazo do PAD","extenso":"Prazo para concluir o processo disciplinar","pratica":"O PAD tem prazo definido para terminar.","tecnica":"Até 60 dias da publicação do ato que constituir a comissão, prorrogáveis por igual prazo. A autoridade julga em 20 dias após receber o processo.","dispositivo":"Lei 8.112/1990, arts. 152 e 167","tags":["PAD","prazos"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Indiciação","extenso":"Acusação formal no PAD","pratica":"Quando a comissão conclui que há infração, formaliza a acusação e aponta os fatos e as provas.","tecnica":"Após a indiciação, o servidor é citado para apresentar defesa escrita em 10 dias (20 dias se houver dois ou mais indiciados).","dispositivo":"Lei 8.112/1990, art. 161","tags":["PAD"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Rito sumário","extenso":"Procedimento disciplinar rápido","pratica":"Processo mais curto para acumulação ilegal de cargos, abandono de cargo e inassiduidade habitual.","tecnica":"Comissão de dois servidores estáveis; conclusão em até 30 dias, prorrogáveis por até 15. Na acumulação, o servidor pode optar por um cargo até o último dia de defesa (boa-fé).","dispositivo":"Lei 8.112/1990, arts. 133 e 140","tags":["PAD"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"],["Ética no Serviço Público","Lei 8.112/1990: acumulação de cargos"]]},{"termo":"Revisão do PAD","extenso":"Reabertura do processo disciplinar","pratica":"O processo pode ser revisto a qualquer tempo se surgirem fatos novos que mostrem inocência ou pena inadequada.","tecnica":"Pedido de ofício ou a requerimento; a revisão não pode agravar a pena.","dispositivo":"Lei 8.112/1990, arts. 174 e 182","tags":["PAD"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: regime disciplinar"]]},{"termo":"Independência das instâncias","extenso":"Esferas civil, penal e administrativa","pratica":"O mesmo fato pode gerar punição civil, penal e administrativa, de forma independente.","tecnica":"Exceção: a absolvição criminal que nega o fato ou a autoria afasta a responsabilidade administrativa.","dispositivo":"Lei 8.112/1990, arts. 125 e 126","tags":["responsabilidade"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Valer-se do cargo","extenso":"Proibição de usar o cargo em proveito próprio","pratica":"É proibido usar o cargo para obter vantagem pessoal ou para outra pessoa, em detrimento da dignidade da função.","tecnica":"Infração punida com demissão. FGV 2022 (q. 12) tratou de servidor que usava terceirizados em negócio particular.","dispositivo":"Lei 8.112/1990, art. 117, IX","tags":["proibições"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: deveres e proibições"],["Ética no Serviço Público","Lei 8.112/1990: responsabilidades e penalidades"]]},{"termo":"Gerência de sociedade privada","extenso":"Proibição de administrar empresa","pratica":"O servidor não pode ser gerente ou administrador de sociedade privada nem exercer comércio.","tecnica":"Pode ser acionista, cotista ou comanditário. Há exceções, como participação em conselhos de empresas em que a União tenha participação.","dispositivo":"Lei 8.112/1990, art. 117, X","tags":["proibições"],"materias":["Ética no Serviço Público"],"topicos":[["Ética no Serviço Público","Lei 8.112/1990: deveres e proibições"]]},{"termo":"Dolo na improbidade","extenso":"Exigência de dolo na Lei 8.429","pratica":"Desde 2021, só há improbidade com dolo: vontade livre e consciente de alcançar o resultado ilícito.","tecnica":"A Lei 14.230/2021 acabou com a improbidade culposa. Mero exercício da função ou divergência de interpretação da lei não configura improbidade.","dispositivo":"Lei 8.429/1992, art. 1º, §§ 1º a 3º","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992 (improbidade): disposições gerais"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"ANPC","extenso":"Acordo de não persecução civil","pratica":"Acordo entre o MP e o acusado de improbidade para encerrar a ação mediante ressarcimento e outras condições.","tecnica":"Exige ressarcimento integral do dano e reversão da vantagem indevida.","dispositivo":"Lei 8.429/1992, art. 17-B","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992 (improbidade): disposições gerais"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Prescrição na improbidade","extenso":"Prazo para punir improbidade","pratica":"A ação de improbidade prescreve em 8 anos.","tecnica":"Contados da ocorrência do fato ou, nas infrações permanentes, do dia em que cessou a permanência. O ressarcimento ao erário por ato doloso é imprescritível (STF).","dispositivo":"Lei 8.429/1992, art. 23","tags":["improbidade","prazos"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992 (improbidade): disposições gerais"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Indisponibilidade de bens","extenso":"Bloqueio de bens na improbidade","pratica":"O juiz pode bloquear bens do acusado para garantir o ressarcimento.","tecnica":"Exige demonstração de perigo de dano irreparável ou de risco ao resultado útil do processo (não é mais presumido).","dispositivo":"Lei 8.429/1992, art. 16","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992 (improbidade): disposições gerais"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Rol do art. 11 da LIA","extenso":"Atos contra os princípios","pratica":"Os atos que violam princípios da administração estão listados de forma fechada no art. 11.","tecnica":"Desde 2021, o rol é taxativo: só há improbidade por violação a princípios nas hipóteses descritas. Cebraspe 2013 cobrou que a improbidade não se restringe a sigilo.","dispositivo":"Lei 8.429/1992, art. 11","tags":["improbidade"],"materias":["Ética no Serviço Público","Noções de Direito Administrativo"],"topicos":[["Ética no Serviço Público","Lei 8.429/1992: atos de improbidade administrativa"],["Noções de Direito Administrativo","Improbidade administrativa"]]},{"termo":"Câmara","extenso":"Órgão fracionário do Tribunal","pratica":"Grupo de desembargadores que julga certas matérias reunindo Turmas: no TJDFT há Câmaras Cíveis e a Câmara Criminal.","tecnica":"As Câmaras julgam, por exemplo, ações rescisórias, conflitos de competência e incidentes entre Turmas da mesma especialidade. Confira a competência de cada uma no RITJDFT.","dispositivo":null,"tags":["órgãos"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Câmaras e Turmas"]]},{"termo":"Turma","extenso":"Órgão fracionário de julgamento","pratica":"Colegiado menor de desembargadores que julga a maior parte dos recursos (apelações, agravos).","tecnica":"No TJDFT as Turmas são Cíveis ou Criminais. Turma Recursal é outra coisa: pertence aos Juizados Especiais e é composta de juízes de primeiro grau.","dispositivo":null,"tags":["órgãos"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Câmaras e Turmas"]]},{"termo":"Turma Recursal","extenso":"Órgão recursal dos Juizados Especiais","pratica":"Colegiado de juízes de primeiro grau que julga os recursos contra sentenças dos Juizados Especiais.","tecnica":"Não integra o segundo grau do Tribunal. Recurso inominado (cível) e apelação (criminal, Lei 9.099) vão à Turma Recursal.","dispositivo":null,"tags":["juizados"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Regimento Interno do TJDFT"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juizados Especiais"],["Regimento Interno do TJDFT","Câmaras e Turmas"]]},{"termo":"Órgão fracionário","extenso":"Parte do Tribunal com competência própria","pratica":"Qualquer colegiado menor que o Pleno: Conselho Especial, Câmaras e Turmas.","tecnica":"Pela cláusula de reserva de plenário (CF, art. 97), órgão fracionário não declara inconstitucionalidade de lei; envia ao Pleno ou ao órgão especial, salvo se já houver pronunciamento deles ou do STF.","dispositivo":"CF, art. 97","tags":["órgãos"],"materias":["Regimento Interno do TJDFT","Noções de Direito Constitucional"],"topicos":[["Regimento Interno do TJDFT","Câmaras e Turmas"],["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Reserva de plenário","extenso":"Cláusula do art. 97 da CF","pratica":"Só a maioria absoluta do Tribunal Pleno ou do órgão especial pode declarar uma lei inconstitucional.","tecnica":"Súmula Vinculante 10: viola a cláusula a decisão de órgão fracionário que, sem declarar expressamente, afasta a aplicação da lei. No TJDFT o órgão especial é o Conselho Especial.","dispositivo":"CF, art. 97; SV 10","tags":["constitucionalidade"],"materias":["Regimento Interno do TJDFT","Noções de Direito Constitucional"],"topicos":[["Regimento Interno do TJDFT","Tribunal Pleno, Conselho Especial e Conselho da Magistratura"],["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Órgão especial","extenso":"Órgão que exerce competências do Pleno","pratica":"Em tribunais com mais de 25 julgadores, pode ser criado um órgão com 11 a 25 membros para exercer atribuições do Pleno.","tecnica":"Metade das vagas por antiguidade e metade por eleição do Pleno. No TJDFT, essa função cabe ao Conselho Especial.","dispositivo":"CF, art. 93, XI","tags":["órgãos"],"materias":["Regimento Interno do TJDFT","Noções de Direito Constitucional"],"topicos":[["Regimento Interno do TJDFT","Tribunal Pleno, Conselho Especial e Conselho da Magistratura"],["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Eleição dos dirigentes","extenso":"Escolha de Presidente, Vice-Presidentes e Corregedor","pratica":"Os cargos de direção do Tribunal são preenchidos por eleição entre os desembargadores mais antigos.","tecnica":"Mandato de 2 anos, vedada a reeleição (LOMAN, art. 102). Quem exerceu cargo de direção por 4 anos ou o de Presidente fica inelegível até esgotar a lista de antiguidade.","dispositivo":"LOMAN (LC 35/1979), art. 102","tags":["direção"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Eleições, posse e substituições"]]},{"termo":"Posse","extenso":"Investidura no cargo","pratica":"Ato pelo qual o eleito ou nomeado assume formalmente o cargo, com compromisso.","tecnica":"No Tribunal, a posse dos dirigentes ocorre em sessão solene do Pleno. Na Lei 8.112, posse é a assinatura do termo e ocorre em até 30 dias da nomeação.","dispositivo":null,"tags":["provimento"],"materias":["Regimento Interno do TJDFT","Noções de Direito Administrativo"],"topicos":[["Regimento Interno do TJDFT","Eleições, posse e substituições"],["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Substituição regimental","extenso":"Quem assume na ausência","pratica":"Regras que dizem quem substitui o Presidente, o relator ou o desembargador em férias ou afastado.","tecnica":"Em geral, segue a ordem de antiguidade ou a designação prevista no RITJDFT. Pergunte-se sempre: substituição eventual (ausência curta) ou convocação de juiz (vaga ou afastamento longo)?","dispositivo":null,"tags":["substituição"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Eleições, posse e substituições"]]},{"termo":"Antiguidade","extenso":"Critério de tempo na carreira","pratica":"Ordem dos magistrados pelo tempo de exercício; decide preferências, substituições e promoções.","tecnica":"Promoção na magistratura alterna antiguidade e merecimento. Na antiguidade, o Tribunal só recusa o mais antigo por voto fundamentado de 2/3 dos membros.","dispositivo":"CF, art. 93, II, d","tags":["carreira"],"materias":["Regimento Interno do TJDFT","Noções de Direito Constitucional"],"topicos":[["Regimento Interno do TJDFT","Eleições, posse e substituições"],["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Comissão permanente","extenso":"Comissão regimental fixa","pratica":"Grupo de desembargadores que cuida de um tema de forma contínua (ex.: regimento, jurisprudência, acervo).","tecnica":"Diferente da comissão temporária, criada para um fim específico e extinta quando o cumpre.","dispositivo":null,"tags":["órgãos"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Comissões permanentes e temporárias"]]},{"termo":"Comissão temporária","extenso":"Comissão para tarefa específica","pratica":"Grupo criado para um trabalho determinado, que se encerra ao concluí-lo.","tecnica":"Designada pelo Presidente ou pelo Pleno conforme o RITJDFT; não confundir com comissão permanente.","dispositivo":null,"tags":["órgãos"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Comissões permanentes e temporárias"]]},{"termo":"Distribuição","extenso":"Sorteio do processo a um relator","pratica":"Ato que define, por sorteio eletrônico e de forma alternada, qual relator ou órgão julgará o processo.","tecnica":"Respeita a prevenção, a igualdade e a publicidade. Distribuição por dependência ocorre quando já há relator prevento.","dispositivo":null,"tags":["distribuição"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Registro, distribuição e prevenção"],["Noções de Direito Processual Civil","Distribuição, registro e valor da causa"]]},{"termo":"Distribuição por dependência","extenso":"Distribuição vinculada a processo anterior","pratica":"O processo vai direto ao juiz ou relator que já cuida de causa ligada a ele.","tecnica":"CPC, art. 286: conexão ou continência; reiteração de pedido após extinção sem mérito; ações com risco de decisões conflitantes.","dispositivo":"CPC, art. 286","tags":["distribuição"],"materias":["Noções de Direito Processual Civil","Regimento Interno do TJDFT"],"topicos":[["Noções de Direito Processual Civil","Distribuição, registro e valor da causa"],["Regimento Interno do TJDFT","Registro, distribuição e prevenção"]]},{"termo":"Preparo","extenso":"Pagamento das custas do recurso","pratica":"Recolhimento das custas e do porte de remessa e retorno para o recurso ser processado.","tecnica":"Comprovado no ato de interpor (CPC, art. 1.007). Insuficiente: intimação para completar em 5 dias. Não comprovado: pagamento em dobro. Isentos: MP, entes públicos, beneficiários da gratuidade.","dispositivo":"CPC, art. 1.007","tags":["recursos"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Preparo e deserção"],["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Deserção","extenso":"Recurso não conhecido por falta de preparo","pratica":"Se o recorrente não paga as custas do recurso, ele é considerado deserto e não é julgado.","tecnica":"Antes de declarar a deserção, o relator deve intimar para recolher em dobro (ausência) ou completar (insuficiência). Justo impedimento afasta a pena.","dispositivo":"CPC, art. 1.007, §§ 2º a 6º","tags":["recursos"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Preparo e deserção"],["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Pauta de julgamento","extenso":"Lista de processos de uma sessão","pratica":"Relação publicada dos processos que serão julgados numa sessão.","tecnica":"Entre a publicação da pauta e a sessão, prazo mínimo de 5 dias úteis (CPC, art. 935). Processo não julgado fica para a próxima sessão sem nova publicação.","dispositivo":"CPC, art. 935","tags":["sessões"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"]]},{"termo":"Sustentação oral","extenso":"Fala do advogado na sessão","pratica":"Momento em que o advogado expõe oralmente suas razões antes do voto.","tecnica":"15 minutos para cada parte, após o relatório (CPC, art. 937). Cabe em apelação, recurso ordinário, especial, extraordinário, embargos de divergência, rescisória, MS e agravo contra tutela provisória.","dispositivo":"CPC, art. 937","tags":["sessões"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"],["Noções de Direito Processual Civil","Apelação, agravo de instrumento e agravo interno"]]},{"termo":"Pedido de vista","extenso":"Adiamento para examinar o processo","pratica":"Julgador que não se sente apto a votar pede o processo para examinar melhor.","tecnica":"Prazo de 10 dias, prorrogável por mais 10; depois, o processo é reincluído em pauta automaticamente (CPC, art. 940).","dispositivo":"CPC, art. 940","tags":["sessões"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"]]},{"termo":"Técnica de ampliação do colegiado","extenso":"Julgamento estendido","pratica":"Quando a apelação não é unânime, o julgamento continua com novos julgadores para permitir inversão do resultado.","tecnica":"CPC, art. 942: substitui os antigos embargos infringentes. Aplica-se também à rescisória que rescinde a sentença e ao agravo que reforma decisão de mérito parcial.","dispositivo":"CPC, art. 942","tags":["sessões"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"],["Noções de Direito Processual Civil","Apelação, agravo de instrumento e agravo interno"]]},{"termo":"Revisor","extenso":"Segundo julgador a examinar o processo","pratica":"Desembargador que revisa o processo depois do relator em certos feitos.","tecnica":"O CPC/2015 extinguiu o revisor no processo civil. No processo penal, ainda existe em alguns recursos e ações penais originárias, conforme o regimento.","dispositivo":null,"tags":["julgamento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Sessões, pauta e julgamento"]]},{"termo":"Ação originária","extenso":"Processo que começa no Tribunal","pratica":"Causa que não passa pela primeira instância: já nasce no Tribunal por causa da matéria ou da autoridade.","tecnica":"Ex.: MS contra ato de desembargador, ação rescisória, ação penal contra autoridades com foro no TJDFT. Diferente de recurso, que leva ao Tribunal causa já julgada pelo juiz.","dispositivo":null,"tags":["competência"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Processos de competência originária, recursos e incidentes"]]},{"termo":"Ação rescisória","extenso":"Ação para desfazer decisão transitada em julgado","pratica":"Ação que pede a anulação de uma decisão de mérito já definitiva, por vícios graves listados na lei.","tecnica":"Prazo de 2 anos do trânsito em julgado da última decisão (CPC, art. 975). Julgada pelo próprio Tribunal (competência originária).","dispositivo":"CPC, arts. 966 e 975","tags":["rescisória"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Processos de competência originária, recursos e incidentes"],["Noções de Direito Processual Civil","Sentença e coisa julgada"]]},{"termo":"Conflito de competência","extenso":"Disputa sobre quem deve julgar","pratica":"Dois ou mais juízes se dizem competentes (positivo) ou incompetentes (negativo) para a mesma causa.","tecnica":"Também ocorre quando há controvérsia sobre reunião ou separação de processos (CPC, art. 66). Julgado pelo tribunal a que os juízes estão vinculados.","dispositivo":"CPC, art. 66","tags":["competência"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Processos de competência originária, recursos e incidentes"],["Noções de Direito Processual Civil","Competência: disposições gerais, modificação e incompetência"]]},{"termo":"IRDR","extenso":"Incidente de resolução de demandas repetitivas","pratica":"Mecanismo que fixa uma tese única para muitos processos com a mesma questão de direito.","tecnica":"Requisitos: repetição efetiva de processos e risco à isonomia e à segurança jurídica. Suspende os processos na área do tribunal; a tese vincula juízes e Juizados.","dispositivo":"CPC, arts. 976 a 987","tags":["precedentes"],"materias":["Regimento Interno do TJDFT","Noções de Direito Processual Civil"],"topicos":[["Regimento Interno do TJDFT","Uniformização de jurisprudência, IRDR e súmulas"],["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"IAC","extenso":"Incidente de assunção de competência","pratica":"Leva o julgamento de recurso com questão relevante, sem repetição em massa, a um órgão colegiado maior.","tecnica":"Diferente do IRDR, não exige multiplicidade de processos. O acórdão vincula juízes e órgãos fracionários.","dispositivo":"CPC, art. 947","tags":["precedentes"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Uniformização de jurisprudência, IRDR e súmulas"]]},{"termo":"Súmula","extenso":"Enunciado da jurisprudência dominante","pratica":"Frase curta que resume o entendimento consolidado de um tribunal.","tecnica":"Tribunais devem uniformizar e manter a jurisprudência estável, íntegra e coerente (CPC, art. 926). Só a súmula vinculante do STF obriga toda a administração pública.","dispositivo":"CPC, art. 926","tags":["precedentes"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Uniformização de jurisprudência, IRDR e súmulas"]]},{"termo":"Emenda regimental","extenso":"Alteração do Regimento Interno","pratica":"Norma aprovada pelo Pleno que altera o texto do Regimento Interno.","tecnica":"O edital cobra o RITJDFT com as emendas posteriores; questões costumam explorar competências alteradas.","dispositivo":null,"tags":["regimento"],"materias":["Regimento Interno do TJDFT"],"topicos":[["Regimento Interno do TJDFT","Emendas Regimentais posteriores a 2016"]]},{"termo":"Lei 11.697/2008","extenso":"Lei de Organização Judiciária do DF e dos Territórios","pratica":"Lei federal que organiza a Justiça do DF: composição do TJDFT, circunscrições, varas e competências.","tecnica":"É lei federal porque a União organiza e mantém o Poder Judiciário do DF (CF, art. 21, XIII, e art. 22, XVII).","dispositivo":"CF, art. 21, XIII","tags":["organização judiciária"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Lei 11.697/2008: disposições gerais e composição da Justiça do DF"]]},{"termo":"Primeiro grau","extenso":"Primeira instância","pratica":"Onde o processo começa: juízes de direito nas varas e nos juizados.","tecnica":"O segundo grau é o Tribunal (desembargadores), que julga recursos e ações originárias.","dispositivo":null,"tags":["organização judiciária"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Lei 11.697/2008: disposições gerais e composição da Justiça do DF"],["Lei de Organização Judiciária do DF e dos Territórios","Circunscrições judiciárias e Varas"]]},{"termo":"Vara de Fazenda Pública do DF","extenso":"Vara das causas do Distrito Federal","pratica":"Julga as causas em que o DF ou suas autarquias e fundações forem parte.","tecnica":"Distinga das varas cíveis comuns e dos Juizados Especiais da Fazenda Pública (causas até 60 salários mínimos, Lei 12.153/2009).","dispositivo":null,"tags":["competência"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Competência das Varas"]]},{"termo":"Juizado Especial da Fazenda Pública","extenso":"Juizado para causas contra o Estado","pratica":"Julga causas cíveis de menor valor contra o DF, autarquias, fundações e empresas públicas distritais.","tecnica":"Até 60 salários mínimos; competência absoluta onde instalado (Lei 12.153/2009). Não cabe para MS, desapropriação ou demandas coletivas.","dispositivo":"Lei 12.153/2009","tags":["juizados"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juizados Especiais"]]},{"termo":"Juizado Especial Cível","extenso":"Juizado das pequenas causas","pratica":"Julga causas cíveis simples, de até 40 salários mínimos, com rito rápido.","tecnica":"Até 20 salários mínimos a parte pode atuar sem advogado (Lei 9.099/1995, art. 9º). Pessoa jurídica de direito público não pode ser parte.","dispositivo":"Lei 9.099/1995","tags":["juizados"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juizados Especiais"]]},{"termo":"Juizado Especial Criminal","extenso":"Juizado das infrações de menor potencial ofensivo","pratica":"Julga contravenções e crimes com pena máxima de até 2 anos.","tecnica":"Admite transação penal e composição civil dos danos. Não se aplica à violência doméstica contra a mulher (Lei 11.340, art. 41).","dispositivo":"Lei 9.099/1995, art. 61","tags":["juizados"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Noções de Direito Processual Penal"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juizados Especiais"],["Noções de Direito Processual Penal","Processo comum e instrução criminal"]]},{"termo":"Vara de Execuções Penais","extenso":"VEP","pratica":"Vara que acompanha o cumprimento das penas: progressão de regime, livramento condicional, remição.","tecnica":"No DF, a competência e a organização vêm da LOJDFT. Não confundir com a vara criminal que proferiu a condenação.","dispositivo":null,"tags":["competência"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Competência das Varas"]]},{"termo":"Juiz de Direito","extenso":"Juiz titular de vara","pratica":"Magistrado de primeiro grau titular de uma vara.","tecnica":"Entra na carreira como Juiz de Direito Substituto, por concurso de provas e títulos, e é promovido por antiguidade e merecimento.","dispositivo":null,"tags":["magistratura"],"materias":["Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juízes de Direito e Juízes de Direito Substitutos"]]},{"termo":"Vitaliciedade","extenso":"Garantia de permanência do juiz","pratica":"Após 2 anos de exercício no primeiro grau, o juiz só perde o cargo por sentença judicial transitada em julgado.","tecnica":"Antes disso, a perda depende de deliberação do tribunal. Quem entra pelo quinto constitucional é vitalício desde a posse.","dispositivo":"CF, art. 95, I","tags":["garantias"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Noções de Direito Constitucional"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Juízes de Direito e Juízes de Direito Substitutos"],["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Serventia judicial","extenso":"Cartório do juízo","pratica":"Unidade administrativa que dá andamento aos processos de uma vara (o ofício judicial ou secretaria).","tecnica":"Integra os serviços auxiliares da Justiça. O diretor de secretaria responde pela organização do cartório.","dispositivo":null,"tags":["serviços auxiliares"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Provimento Geral da Corregedoria"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Serviços auxiliares da Justiça"],["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Oficial de justiça","extenso":"Servidor que cumpre ordens do juiz fora do cartório","pratica":"Faz citações, intimações, penhoras e outras diligências determinadas pelo juiz.","tecnica":"No CPC é auxiliar da Justiça (art. 154): certifica o que fez e pode certificar proposta de autocomposição.","dispositivo":"CPC, art. 154","tags":["serviços auxiliares"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Noções de Direito Processual Civil"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Serviços auxiliares da Justiça"],["Noções de Direito Processual Civil","Auxiliares da Justiça"]]},{"termo":"Distribuidor","extenso":"Serviço que reparte os processos","pratica":"Setor que registra e distribui os processos entre as varas competentes.","tecnica":"Garante alternância e aleatoriedade. É um dos auxiliares da Justiça listados no CPC (art. 149).","dispositivo":null,"tags":["serviços auxiliares"],"materias":["Lei de Organização Judiciária do DF e dos Territórios","Noções de Direito Processual Civil"],"topicos":[["Lei de Organização Judiciária do DF e dos Territórios","Serviços auxiliares da Justiça"],["Noções de Direito Processual Civil","Distribuição, registro e valor da causa"]]},{"termo":"Diretor de secretaria","extenso":"Chefe do cartório","pratica":"Servidor que dirige o ofício judicial: organiza o serviço, confere atos e assina expedientes.","tecnica":"Responde pela guarda dos autos e pelo cumprimento das ordens judiciais; pode praticar atos ordinatórios.","dispositivo":null,"tags":["ofício judicial"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"],["Provimento Geral da Corregedoria","Provimento Geral da Corregedoria aplicado aos Juízes e Ofícios Judiciais (2014) e alterações"]]},{"termo":"Termo de juntada","extenso":"Registro da inclusão de peça nos autos","pratica":"Certificação de que um documento foi anexado ao processo.","tecnica":"No processo eletrônico a juntada é automática pelo sistema; no físico, é registrada por termo com data.","dispositivo":null,"tags":["ofício judicial"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Abertura de vista","extenso":"Envio dos autos à parte ou ao MP","pratica":"Ato que encaminha o processo para manifestação de alguém.","tecnica":"Deve ser registrada nos autos com data. O prazo começa a correr na forma da intimação.","dispositivo":null,"tags":["ofício judicial"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Certidão de decurso de prazo","extenso":"Registro de que o prazo acabou","pratica":"Documento do cartório que atesta que o prazo terminou, com ou sem manifestação.","tecnica":"Base para atos seguintes, como trânsito em julgado e revelia.","dispositivo":null,"tags":["certidões"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Mandado","extenso":"Ordem escrita do juiz","pratica":"Documento que leva a ordem judicial para ser cumprida pelo oficial de justiça.","tecnica":"Mandado de citação, intimação, penhora, prisão. O oficial certifica o cumprimento no próprio mandado.","dispositivo":null,"tags":["comunicação"],"materias":["Provimento Geral da Corregedoria","Noções de Direito Processual Civil"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"],["Noções de Direito Processual Civil","Comunicação dos atos processuais"]]},{"termo":"Correição","extenso":"Fiscalização dos serviços judiciais","pratica":"Inspeção feita pela Corregedoria nas unidades judiciais para verificar a regularidade dos serviços.","tecnica":"Ordinária (periódica) ou extraordinária (por fato específico). O juiz faz correição permanente na própria unidade.","dispositivo":null,"tags":["corregedoria"],"materias":["Provimento Geral da Corregedoria","Regimento Interno do TJDFT"],"topicos":[["Provimento Geral da Corregedoria","Provimento Geral da Corregedoria aplicado aos Juízes e Ofícios Judiciais (2014) e alterações"],["Regimento Interno do TJDFT","Presidência, Vice-Presidências e Corregedoria"]]},{"termo":"Arquivamento","extenso":"Guarda definitiva ou provisória do processo","pratica":"Encerramento do andamento do processo no cartório, com registro e baixa.","tecnica":"Pode ser provisório (ex.: aguardando bens para penhora) ou definitivo. Desarquivar exige pedido e registro.","dispositivo":null,"tags":["ofício judicial"],"materias":["Provimento Geral da Corregedoria"],"topicos":[["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Segredo de justiça","extenso":"Processo com acesso restrito","pratica":"Processo que só as partes e seus advogados podem consultar.","tecnica":"CPC, art. 189: interesse público, família, dados protegidos pela intimidade e arbitragem com confidencialidade. No PJe, o sigilo é marcado no cadastro.","dispositivo":"CPC, art. 189","tags":["sigilo"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Provimento Judicial aplicado ao Processo Judicial Eletrônico (2017) e alterações"],["Noções de Direito Processual Civil","Atos processuais: forma, tempo, lugar e prazos"]]},{"termo":"Credenciamento no PJe","extenso":"Cadastro para usar o sistema","pratica":"Advogados e partes precisam se cadastrar e usar certificado digital ou login para peticionar.","tecnica":"Lei 11.419/2006, art. 2º: o envio de petições por meio eletrônico exige credenciamento prévio no Poder Judiciário.","dispositivo":"Lei 11.419/2006, art. 2º","tags":["PJe"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"Indisponibilidade do sistema","extenso":"Falha do PJe","pratica":"Quando o sistema fica fora do ar, os prazos que venceriam naquele dia são prorrogados.","tecnica":"Prorroga-se para o primeiro dia útil seguinte à resolução do problema (Lei 11.419, art. 10, § 2º).","dispositivo":"Lei 11.419/2006, art. 10, § 2º","tags":["PJe","prazos"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"Petição tempestiva no PJe","extenso":"Prazo até 24 horas","pratica":"No processo eletrônico, a petição enviada até as 24 horas do último dia é tempestiva.","tecnica":"Lei 11.419/2006, art. 3º, parágrafo único. Considera-se o horário de Brasília.","dispositivo":"Lei 11.419/2006, art. 3º","tags":["PJe","prazos"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Processo judicial eletrônico: Lei 11.419/2006"]]},{"termo":"Intimação tácita","extenso":"Intimação após 10 dias sem consulta","pratica":"No sistema eletrônico, se o intimado não abre a intimação em 10 dias corridos, considera-se intimado no fim desse prazo.","tecnica":"Lei 11.419/2006, art. 5º, § 3º. Se consultar antes, a intimação ocorre no dia da consulta.","dispositivo":"Lei 11.419/2006, art. 5º","tags":["PJe","intimações"],"materias":["Provimento Judicial aplicado ao PJe","Noções de Direito Processual Civil"],"topicos":[["Provimento Judicial aplicado ao PJe","Peticionamento, intimações e prazos no PJe"],["Noções de Direito Processual Civil","Comunicação dos atos processuais"]]},{"termo":"Gestão de pessoas","extenso":"Área que cuida das pessoas na organização","pratica":"Conjunto de práticas para atrair, desenvolver, manter e avaliar as pessoas, tratadas como parceiras e não como recurso.","tecnica":"Evolução: departamento de pessoal (foco legal e operacional) → recursos humanos (foco em controle) → gestão estratégica de pessoas (alinhada aos objetivos da organização).","dispositivo":null,"tags":["gestão de pessoas"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão de pessoas e sua evolução"],["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão estratégica de pessoas"]]},{"termo":"Departamento de pessoal","extenso":"Modelo operacional e legalista","pratica":"Fase inicial da área de RH, focada em folha de pagamento, admissões, férias e cumprimento da lei.","tecnica":"Visão do trabalhador como custo e de tarefas burocráticas; sucedido pelo modelo de RH e depois pela gestão estratégica.","dispositivo":null,"tags":["gestão de pessoas"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão de pessoas e sua evolução"]]},{"termo":"Processos de gestão de pessoas","extenso":"Seis processos de Chiavenato","pratica":"Agregar, aplicar, recompensar, desenvolver, manter e monitorar pessoas.","tecnica":"Agregar: recrutamento e seleção. Aplicar: desenho de cargos e avaliação. Recompensar: remuneração e benefícios. Desenvolver: T&D. Manter: higiene, segurança, qualidade de vida. Monitorar: bancos de dados e sistemas de informação.","dispositivo":null,"tags":["Chiavenato"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Processos de gestão de pessoas"]]},{"termo":"Recrutamento","extenso":"Atrair candidatos","pratica":"Divulgar a vaga e atrair pessoas qualificadas para o processo seletivo.","tecnica":"Interno (pessoas da própria organização, mais barato e motivador) ou externo (traz novas ideias, mais caro e demorado). Misto combina os dois.","dispositivo":null,"tags":["agregar"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Processos de gestão de pessoas"]]},{"termo":"Seleção de pessoas","extenso":"Escolher entre os candidatos","pratica":"Comparar os candidatos com o perfil do cargo e escolher o mais adequado.","tecnica":"Técnicas: entrevista, provas de conhecimento, testes psicológicos, técnicas de simulação. No setor público, a seleção é por concurso (CF, art. 37, II).","dispositivo":null,"tags":["agregar"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Processos de gestão de pessoas"]]},{"termo":"Endomarketing","extenso":"Marketing interno","pratica":"Ações de comunicação voltadas aos próprios servidores para engajá-los nos objetivos da organização.","tecnica":"Ajuda a sustentar mudanças e a reforçar valores e missão.","dispositivo":null,"tags":["comunicação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Estratégias de gestão de pessoas para sustentar a mudança"],["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão estratégica de pessoas"]]},{"termo":"Clima organizacional","extenso":"Percepção coletiva do ambiente de trabalho","pratica":"Como as pessoas sentem a organização: satisfação, relacionamento, motivação.","tecnica":"Medido por pesquisa de clima. Cultura é mais profunda e duradoura (valores e crenças); clima é mais momentâneo.","dispositivo":null,"tags":["clima"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Indicadores de desempenho de gestão de pessoas"],["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Cultura organizacional","extenso":"Valores e crenças compartilhados","pratica":"Jeito de ser e de fazer da organização, aprendido e passado entre as pessoas.","tecnica":"Níveis (Schein): artefatos visíveis, valores declarados e pressupostos básicos. É a principal fonte de resistência à mudança.","dispositivo":null,"tags":["cultura"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão de processos de mudança organizacional: conceito de mudança"],["Noções de Administração de Recursos Humanos e Gestão Pública","Mudança e inovação organizacional"]]},{"termo":"Resistência à mudança","extenso":"Oposição às mudanças","pratica":"Reação de pessoas ou grupos que se opõem a mudanças por medo, hábito ou perda de poder.","tecnica":"Superada com comunicação, participação, treinamento, negociação e apoio. Kotter: criar senso de urgência, formar coalizão, comunicar a visão, gerar vitórias de curto prazo e ancorar na cultura.","dispositivo":null,"tags":["mudança"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão de processos de mudança organizacional: conceito de mudança"],["Noções de Administração de Recursos Humanos e Gestão Pública","Estratégias de gestão de pessoas para sustentar a mudança"]]},{"termo":"Modelo de Lewin","extenso":"Descongelamento, mudança e recongelamento","pratica":"Três etapas da mudança: desfazer os velhos hábitos, implantar o novo e consolidar o novo comportamento.","tecnica":"Clássico em provas sobre gestão da mudança organizacional. A mudança só se sustenta se for recongelada.","dispositivo":null,"tags":["mudança"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão de processos de mudança organizacional: conceito de mudança"]]},{"termo":"Mudança incremental","extenso":"Mudança gradual","pratica":"Pequenos ajustes contínuos que melhoram o que já existe.","tecnica":"Contrasta com a mudança radical (transformacional), que altera profundamente a estrutura ou a estratégia.","dispositivo":null,"tags":["mudança"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão de processos de mudança organizacional: conceito de mudança"],["Noções de Administração de Recursos Humanos e Gestão Pública","Mudança e inovação organizacional"]]},{"termo":"Inovação","extenso":"Novidade que gera valor","pratica":"Implantação de algo novo ou melhorado (produto, serviço, processo) que traz resultado.","tecnica":"Pode ser incremental ou radical. No setor público, aparece em serviços digitais, simplificação e laboratórios de inovação.","dispositivo":null,"tags":["inovação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Mudança e inovação organizacional"]]},{"termo":"Ambiente interno","extenso":"Fatores dentro da organização","pratica":"Pontos que a organização controla: pessoas, estrutura, processos, recursos.","tecnica":"Na SWOT, gera forças e fraquezas. O ambiente externo gera oportunidades e ameaças.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Análise dos ambientes interno e externo"]]},{"termo":"Análise PESTEL","extenso":"Análise do macroambiente","pratica":"Ferramenta que examina fatores Políticos, Econômicos, Sociais, Tecnológicos, Ecológicos e Legais.","tecnica":"Útil para mapear oportunidades e ameaças externas antes do planejamento estratégico.","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Análise dos ambientes interno e externo"]]},{"termo":"Planejamento estratégico","extenso":"Definição de rumo de longo prazo","pratica":"Processo que define missão, visão, valores, objetivos e ações para a organização.","tecnica":"Níveis: estratégico (longo prazo, toda a organização), tático (médio prazo, departamentos), operacional (curto prazo, tarefas).","dispositivo":null,"tags":["estratégia"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Missão, visão de futuro e valores"],["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão estratégica de pessoas"]]},{"termo":"Balanced Scorecard","extenso":"BSC","pratica":"Ferramenta que traduz a estratégia em indicadores de quatro perspectivas.","tecnica":"Perspectivas: financeira, clientes, processos internos e aprendizado e crescimento. No setor público, a perspectiva da sociedade costuma ficar no topo. Usa mapa estratégico com relações de causa e efeito.","dispositivo":null,"tags":["indicadores"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Indicadores de desempenho de gestão de pessoas"],["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão estratégica de pessoas"]]},{"termo":"Indicador de desempenho","extenso":"Medida do resultado","pratica":"Número que mostra se uma meta está sendo cumprida: rotatividade, absenteísmo, horas de treinamento.","tecnica":"Bons indicadores são específicos, mensuráveis, comparáveis e disponíveis a tempo. Meta é o valor a atingir; indicador é o que se mede.","dispositivo":null,"tags":["indicadores"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Indicadores de desempenho de gestão de pessoas"]]},{"termo":"Rotatividade","extenso":"Turnover","pratica":"Taxa de entrada e saída de pessoas numa organização em determinado período.","tecnica":"Alta rotatividade indica problemas de clima, remuneração ou seleção, e gera custos de reposição e treinamento.","dispositivo":null,"tags":["indicadores"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Indicadores de desempenho de gestão de pessoas"]]},{"termo":"Absenteísmo","extenso":"Ausência ao trabalho","pratica":"Faltas e atrasos dos empregados, programados ou não.","tecnica":"Indicador de gestão de pessoas ligado a saúde, motivação e clima organizacional.","dispositivo":null,"tags":["indicadores"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Indicadores de desempenho de gestão de pessoas"]]},{"termo":"Levantamento de necessidades de treinamento","extenso":"LNT, diagnóstico de T&D","pratica":"Primeira etapa do treinamento: descobrir o que as pessoas precisam aprender.","tecnica":"Ciclo de T&D: diagnóstico (LNT) → programação → execução → avaliação. Níveis de avaliação de Kirkpatrick: reação, aprendizagem, comportamento e resultados.","dispositivo":null,"tags":["T&D"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Treinamento e desenvolvimento"]]},{"termo":"Educação corporativa","extenso":"Universidade corporativa","pratica":"Sistema de desenvolvimento contínuo alinhado à estratégia da organização.","tecnica":"Vai além do treinamento pontual: forma competências para o longo prazo. No Judiciário, as escolas de servidores cumprem esse papel.","dispositivo":null,"tags":["T&D"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Treinamento e desenvolvimento"]]},{"termo":"Efeito de leniência","extenso":"Erro de avaliação por complacência","pratica":"O avaliador dá notas altas a todos para evitar conflito.","tecnica":"O efeito oposto é o rigor excessivo; a tendência central é dar notas médias a todos. São vieses da avaliação de desempenho, como o efeito halo.","dispositivo":null,"tags":["avaliação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Avaliação do desempenho humano"]]},{"termo":"Escala gráfica","extenso":"Método de avaliação de desempenho","pratica":"Formulário com fatores (qualidade, pontualidade) e graus (ótimo a fraco) marcados pelo avaliador.","tecnica":"Método mais usado por ser simples, mas sujeito a efeito halo e tendência central. Outros métodos: escolha forçada, incidentes críticos, pesquisa de campo, autoavaliação.","dispositivo":null,"tags":["avaliação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Avaliação do desempenho humano"]]},{"termo":"Incidentes críticos","extenso":"Método de avaliação de desempenho","pratica":"O avaliador registra comportamentos extremos, muito positivos ou muito negativos.","tecnica":"Foca exceções; não avalia o desempenho habitual.","dispositivo":null,"tags":["avaliação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Avaliação do desempenho humano"]]},{"termo":"Enriquecimento de cargo","extenso":"Ampliar responsabilidade e desafio","pratica":"Aumentar a autonomia e as responsabilidades do cargo para torná-lo mais motivador.","tecnica":"Vertical: tarefas mais complexas (mais motivador, segundo Herzberg). Horizontal: mais tarefas do mesmo nível (alargamento).","dispositivo":null,"tags":["cargos"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelagem do trabalho: descrição, análise e desenho de cargos"],["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Modelo clássico de desenho de cargos","extenso":"Desenho de cargos tayloriano","pratica":"Tarefas simples, repetitivas e padronizadas, com separação entre quem planeja e quem executa.","tecnica":"Modelos: clássico (Taylor), humanístico (relações humanas) e contingencial (adapta o cargo à pessoa e à tarefa, mais motivador).","dispositivo":null,"tags":["cargos"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelagem do trabalho: descrição, análise e desenho de cargos"]]},{"termo":"Teoria X e Y","extenso":"Teoria de McGregor","pratica":"Duas visões do trabalhador: X (preguiçoso, precisa de controle) e Y (gosta de trabalhar, busca responsabilidade).","tecnica":"A teoria Y fundamenta estilos participativos de gestão. É teoria de motivação/liderança, não de processo.","dispositivo":null,"tags":["motivação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Teoria da expectativa","extenso":"Teoria de Vroom","pratica":"A motivação depende de quanto a pessoa espera que o esforço gere resultado e de quanto valoriza a recompensa.","tecnica":"Fórmula: motivação = expectativa × instrumentalidade × valência. Teoria de processo, ao contrário de Maslow e Herzberg (conteúdo).","dispositivo":null,"tags":["motivação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Teoria da equidade","extenso":"Teoria de Adams","pratica":"As pessoas comparam o que dão e o que recebem com o de colegas; injustiça percebida desmotiva.","tecnica":"Ao perceber iniquidade, a pessoa pode reduzir o esforço, pedir aumento ou mudar a comparação.","dispositivo":null,"tags":["motivação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Motivação"]]},{"termo":"Competência técnica","extenso":"Saber fazer","pratica":"Conhecimento e habilidade para executar as tarefas do cargo.","tecnica":"Competências podem ser organizacionais (da instituição) ou individuais (técnicas e comportamentais). O mapeamento identifica o gap entre as necessárias e as existentes.","dispositivo":null,"tags":["competências"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão por competências"]]},{"termo":"Mapeamento de competências","extenso":"Diagnóstico de lacunas","pratica":"Identifica as competências necessárias para a estratégia e as compara com as que as pessoas já têm.","tecnica":"A diferença é a lacuna (gap) de competências, que orienta treinamento, seleção e movimentação.","dispositivo":null,"tags":["competências"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Gestão por competências"]]},{"termo":"Nova gestão pública","extenso":"New Public Management","pratica":"Movimento que trouxe ferramentas do setor privado para o Estado: foco em resultados, contratos de gestão, eficiência.","tecnica":"No Brasil, ligado ao Plano Diretor da Reforma do Aparelho do Estado (1995) e à EC 19/1998, que incluiu a eficiência no art. 37.","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão pública: patrimonialista, burocrático e gerencial"]]},{"termo":"Governança pública","extenso":"Direção e controle do Estado","pratica":"Mecanismos de liderança, estratégia e controle para avaliar, direcionar e monitorar a gestão.","tecnica":"Princípios: transparência, accountability, integridade, capacidade de resposta. Governança dirige; gestão executa.","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Modelos de gestão pública: patrimonialista, burocrático e gerencial"],["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"]]},{"termo":"Accountability","extenso":"Responsabilização e prestação de contas","pratica":"Dever de o gestor prestar contas e responder pelos resultados.","tecnica":"Vertical (sociedade sobre governo, eleições), horizontal (órgãos de controle entre si, como TCU) e social.","dispositivo":null,"tags":["gestão pública"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Ética no Serviço Público"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"],["Ética no Serviço Público","Ética e democracia: exercício da cidadania"]]},{"termo":"Economicidade","extenso":"Melhor custo","pratica":"Obter o resultado com o menor custo possível, sem perder qualidade.","tecnica":"Um dos critérios do controle externo (CF, art. 70), ao lado de legalidade e legitimidade.","dispositivo":"CF, art. 70","tags":["desempenho"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Eficácia e efetividade: avaliação e mensuração do desempenho governamental"],["Noções de Direito Administrativo","Controle pelos Tribunais de Contas"]]},{"termo":"Princípio do equilíbrio","extenso":"Princípio orçamentário","pratica":"As despesas autorizadas não devem ultrapassar as receitas previstas.","tecnica":"Reforçado pela LRF. A regra de ouro (CF, art. 167, III) proíbe operações de crédito acima das despesas de capital.","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Princípio da não vinculação","extenso":"Princípio da não afetação da receita","pratica":"É proibido vincular a receita de impostos a órgão, fundo ou despesa.","tecnica":"Exceções na própria CF, art. 167, IV: repartição com estados e municípios, saúde, educação, administração tributária, garantias de operações de crédito.","dispositivo":"CF, art. 167, IV","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Princípio da publicidade orçamentária","extenso":"Divulgação do orçamento","pratica":"O orçamento e sua execução devem ser publicados e acessíveis.","tecnica":"Inclui a transparência da LRF: relatórios de execução e de gestão fiscal.","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Orçamento público: princípios orçamentários"]]},{"termo":"Ciclo orçamentário","extenso":"Etapas do orçamento","pratica":"Elaboração da proposta, discussão e aprovação no Legislativo, execução e controle/avaliação.","tecnica":"Não confundir com o exercício financeiro (ano civil, 1º de janeiro a 31 de dezembro).","dispositivo":null,"tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"]]},{"termo":"Exercício financeiro","extenso":"Período do orçamento","pratica":"Período de execução do orçamento, que no Brasil coincide com o ano civil.","tecnica":"Lei 4.320/1964, art. 34. Pertencem ao exercício as receitas nele arrecadadas e as despesas nele empenhadas (regime misto).","dispositivo":"Lei 4.320/1964, arts. 34 e 35","tags":["orçamento"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Diretrizes orçamentárias, processo orçamentário e emendas ao orçamento"],["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Despesa corrente","extenso":"Despesa de manutenção","pratica":"Gastos para manter os serviços funcionando: pessoal, material de consumo, serviços de terceiros.","tecnica":"Categoria econômica oposta à despesa de capital, que forma ou adquire bens (investimentos, inversões financeiras, amortização da dívida).","dispositivo":null,"tags":["despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Despesa de capital","extenso":"Despesa que forma patrimônio","pratica":"Gastos com obras, equipamentos, compra de imóveis e amortização de dívidas.","tecnica":"Grupos: investimentos, inversões financeiras e amortização da dívida.","dispositivo":null,"tags":["despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Receita corrente","extenso":"Receita das atividades normais","pratica":"Receitas tributárias, de contribuições, patrimoniais, de serviços, transferências correntes.","tecnica":"Receita de capital vem de operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital.","dispositivo":null,"tags":["receita"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Lançamento","extenso":"Estágio da receita","pratica":"Ato que identifica o devedor e calcula o valor da receita.","tecnica":"Estágios da receita: previsão, lançamento, arrecadação e recolhimento. Nem toda receita passa pelo lançamento.","dispositivo":null,"tags":["receita"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Receita e despesa públicas: conceito, classificação e estágios"]]},{"termo":"Despesas de exercícios anteriores","extenso":"DEA","pratica":"Despesas de anos passados pagas com o orçamento do ano atual, quando não foram empenhadas a tempo.","tecnica":"Lei 4.320/1964, art. 37: despesas com saldo suficiente não processadas na época, restos a pagar com prescrição interrompida, compromissos reconhecidos após o encerramento do exercício.","dispositivo":"Lei 4.320/1964, art. 37","tags":["despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"Restos a pagar processados","extenso":"Despesa liquidada e não paga","pratica":"Despesa empenhada e liquidada até 31 de dezembro, ainda não paga.","tecnica":"Não processados: empenhados e ainda não liquidados. A distinção importa para o cancelamento e o controle fiscal.","dispositivo":null,"tags":["despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"Regime de adiantamento","extenso":"Suprimento de fundos","pratica":"Entrega de dinheiro a servidor para gastos que não podem seguir o processo normal de despesa.","tecnica":"Sempre precedido de empenho. Não se concede a servidor responsável por dois suprimentos ou que esteja em alcance (sem prestar contas).","dispositivo":"Lei 4.320/1964, arts. 68 e 69","tags":["despesa"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Suprimento de fundos, restos a pagar e despesas de exercícios anteriores"]]},{"termo":"Etapa preparatória da licitação","extenso":"Fase interna","pratica":"Planejamento da contratação: estudo técnico preliminar, termo de referência, orçamento, análise de riscos.","tecnica":"Lei 14.133/2021, art. 18. Fases: preparatória, divulgação do edital, propostas e lances, julgamento, habilitação, recursal e homologação.","dispositivo":"Lei 14.133/2021, art. 17","tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Agente de contratação","extenso":"Condutor da licitação","pratica":"Servidor efetivo ou empregado público designado para conduzir a licitação.","tecnica":"No pregão, é chamado de pregoeiro. Pode ser substituído por comissão de contratação de, no mínimo, três membros quando houver bens ou serviços especiais.","dispositivo":"Lei 14.133/2021, art. 8º","tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Concorrência","extenso":"Modalidade de licitação","pratica":"Modalidade para bens e serviços especiais e obras e serviços comuns e especiais de engenharia.","tecnica":"Lei 14.133/2021, art. 6º, XXXVIII. Critérios: menor preço, melhor técnica ou conteúdo artístico, técnica e preço, maior retorno econômico ou maior desconto.","dispositivo":"Lei 14.133/2021, art. 6º, XXXVIII","tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Leilão","extenso":"Modalidade de licitação","pratica":"Modalidade para vender bens imóveis ou móveis inservíveis ou apreendidos, a quem der o maior lance.","tecnica":"Pode ser conduzido por leiloeiro oficial ou servidor designado. Não tem habilitação prévia, em regra.","dispositivo":"Lei 14.133/2021, art. 6º, XL","tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Concurso (licitação)","extenso":"Modalidade para trabalho técnico, científico ou artístico","pratica":"Escolhe trabalho intelectual mediante prêmio ou remuneração ao vencedor.","tecnica":"Não confundir com concurso público para cargos. Critério: melhor técnica ou conteúdo artístico.","dispositivo":"Lei 14.133/2021, art. 6º, XXXIX","tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Licitação deserta","extenso":"Nenhum interessado apareceu","pratica":"Licitação em que nenhum licitante se apresentou.","tecnica":"Permite dispensa para nova contratação que mantenha todas as condições do edital, se a licitação foi feita há menos de 1 ano (Lei 14.133, art. 75, III). Fracassada: houve licitantes, mas todos foram inabilitados ou desclassificados.","dispositivo":null,"tags":["licitação"],"materias":["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de Direito Administrativo"],"topicos":[["Noções de Administração de Recursos Humanos e Gestão Pública","Noções de licitação: fases, modalidades, dispensa e inexigibilidade"],["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Constituição promulgada","extenso":"Constituição democrática","pratica":"Feita por representantes eleitos pelo povo (Assembleia Constituinte).","tecnica":"A CF/1988 é promulgada, escrita, dogmática, rígida, formal, analítica e eclética. A outorgada é imposta pelo governante (ex.: 1937).","dispositivo":null,"tags":["classificação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Constituição analítica","extenso":"Constituição extensa","pratica":"Detalha muitos assuntos, inclusive temas que não são essencialmente constitucionais.","tecnica":"Oposta à sintética (curta, só princípios, como a dos EUA). A CF/1988 é analítica.","dispositivo":null,"tags":["classificação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Poder constituinte originário","extenso":"Poder que cria a Constituição","pratica":"Poder de fazer uma nova Constituição, inicial, ilimitado juridicamente e incondicionado.","tecnica":"O derivado reformador (emendas) é limitado pelas cláusulas pétreas, pelo procedimento e pelas circunstâncias (não há emenda durante intervenção federal, estado de defesa ou de sítio).","dispositivo":null,"tags":["poder constituinte"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Eficácia limitada","extenso":"Norma que depende de lei","pratica":"Norma constitucional que só produz todos os efeitos depois que uma lei a regulamenta.","tecnica":"Classificação de José Afonso da Silva: eficácia plena (aplicação imediata), contida (aplicação imediata, mas a lei pode restringir) e limitada (depende de lei).","dispositivo":null,"tags":["eficácia"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Constituição: conceito e classificações"]]},{"termo":"Separação dos Poderes","extenso":"Divisão das funções do Estado","pratica":"Legislativo, Executivo e Judiciário são independentes e harmônicos entre si.","tecnica":"Princípio fundamental (CF, art. 2º) e cláusula pétrea. Há sistema de freios e contrapesos (veto, controle de constitucionalidade, CPI).","dispositivo":"CF, art. 2º","tags":["princípios"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Princípios fundamentais"]]},{"termo":"Dignidade da pessoa humana","extenso":"Fundamento da República","pratica":"Valor que coloca a pessoa como centro e fim do Estado.","tecnica":"Fundamento (art. 1º, III), não objetivo. Fundamentos: soberania, cidadania, dignidade, valores sociais do trabalho e da livre iniciativa, pluralismo político (SOCIDIVAPLU).","dispositivo":"CF, art. 1º, III","tags":["princípios"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Princípios fundamentais"]]},{"termo":"Remédios constitucionais","extenso":"Ações de garantia","pratica":"Ações que protegem direitos fundamentais: habeas corpus, habeas data, mandado de segurança, mandado de injunção e ação popular.","tecnica":"HC e HD são gratuitos; a ação popular é gratuita salvo comprovada má-fé do autor (CF, art. 5º, LXXIII e LXXVII).","dispositivo":"CF, art. 5º","tags":["remédios"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"Inviolabilidade de domicílio","extenso":"A casa é asilo inviolável","pratica":"Ninguém pode entrar na casa sem consentimento do morador.","tecnica":"Exceções: flagrante delito, desastre ou socorro (a qualquer hora); ordem judicial (só durante o dia).","dispositivo":"CF, art. 5º, XI","tags":["direitos individuais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"Direito de reunião","extenso":"Liberdade de reunião","pratica":"Todos podem se reunir pacificamente, sem armas, em locais abertos ao público.","tecnica":"Não depende de autorização; exige apenas aviso prévio à autoridade e não frustrar outra reunião já convocada para o mesmo local.","dispositivo":"CF, art. 5º, XVI","tags":["direitos individuais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos e deveres individuais e coletivos"]]},{"termo":"Direitos sociais","extenso":"Direitos de segunda dimensão","pratica":"Direitos que exigem prestações do Estado: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência, proteção à maternidade e à infância, assistência aos desamparados.","tecnica":"CF, art. 6º. Ligados à igualdade material. Aplicam-se a reserva do possível e a vedação ao retrocesso social.","dispositivo":"CF, art. 6º","tags":["direitos sociais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos sociais"]]},{"termo":"Reserva do possível","extenso":"Limite orçamentário dos direitos","pratica":"Os direitos sociais se realizam dentro da disponibilidade de recursos do Estado.","tecnica":"Não pode ser alegada para negar o mínimo existencial. Construção doutrinária e jurisprudencial, não está escrita na CF.","dispositivo":null,"tags":["direitos sociais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos sociais"]]},{"termo":"Direitos dos trabalhadores","extenso":"Rol do art. 7º da CF","pratica":"Garantias como salário mínimo, 13º, férias com 1/3, FGTS, licença-maternidade de 120 dias, jornada de 8h diárias e 44h semanais.","tecnica":"O rol é exemplificativo (“além de outros que visem à melhoria de sua condição social”).","dispositivo":"CF, art. 7º","tags":["direitos sociais"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos sociais"]]},{"termo":"Direito de greve","extenso":"Greve dos trabalhadores","pratica":"Os trabalhadores decidem quando e por que fazer greve.","tecnica":"Servidor público civil: direito exercido nos termos de lei específica; o STF aplica a lei de greve privada (Lei 7.783/1989) enquanto não vem a lei. Militares não podem fazer greve.","dispositivo":"CF, arts. 9º e 37, VII","tags":["greve"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Direitos sociais"],["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Perda da nacionalidade","extenso":"Quando o brasileiro deixa de ser brasileiro","pratica":"Hoje o brasileiro só perde a nacionalidade em dois casos: naturalização cancelada por sentença (fraude no processo ou atentado contra a ordem constitucional) ou pedido expresso de perda.","tecnica":"Redação da EC 131/2023: adquirir outra nacionalidade já não faz perder a brasileira; o pedido de perda não vale se gerar apatridia, e quem renunciou pode readquirir a nacionalidade.","dispositivo":"CF, art. 12, § 4º","tags":["nacionalidade"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Nacionalidade"]]},{"termo":"Cargos privativos de brasileiro nato","extenso":"Cargos só para natos","pratica":"Presidente e Vice, Presidentes da Câmara e do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas, Ministro de Estado da Defesa.","tecnica":"CF, art. 12, § 3º. Fora desses casos, a lei não pode distinguir natos e naturalizados.","dispositivo":"CF, art. 12, § 3º","tags":["nacionalidade"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Nacionalidade"]]},{"termo":"Sufrágio universal","extenso":"Direito de votar de todos","pratica":"Todos os cidadãos podem votar, sem exigência de renda ou instrução.","tecnica":"Voto direto, secreto, com valor igual para todos. O voto direto, secreto, universal e periódico é cláusula pétrea; a obrigatoriedade não é.","dispositivo":"CF, art. 14","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Idade mínima para eleição","extenso":"Condições de elegibilidade","pratica":"35 anos: Presidente, Vice e Senador; 30: Governador e Vice; 21: Deputado, Prefeito, Vice e juiz de paz; 18: Vereador.","tecnica":"CF, art. 14, § 3º, VI. A idade é verificada na data da posse; para vereador, na data do registro (Lei 9.504, art. 11, § 2º).","dispositivo":"CF, art. 14, § 3º","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Suspensão dos direitos políticos","extenso":"Privação temporária","pratica":"Os direitos políticos ficam suspensos enquanto durar a causa: condenação criminal transitada em julgado, improbidade, incapacidade civil absoluta, recusa a cumprir obrigação a todos imposta.","tecnica":"A CF proíbe a cassação de direitos políticos; só admite perda e suspensão nos casos do art. 15.","dispositivo":"CF, art. 15","tags":["direitos políticos"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Cidadania, direitos políticos e partidos políticos"]]},{"termo":"Distrito Federal","extenso":"Ente federativo com competências de estado e município","pratica":"O DF não se divide em municípios e acumula competências estaduais e municipais.","tecnica":"Regido por lei orgânica. A União organiza e mantém o Judiciário, o MP, a Defensoria, a polícia civil, a penal, a militar e o corpo de bombeiros do DF.","dispositivo":"CF, art. 32","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"Intervenção federal","extenso":"Afastamento temporário da autonomia","pratica":"A União intervém em estado ou no DF apenas nos casos taxativos da CF, como manter a integridade nacional ou garantir o cumprimento de ordem judicial.","tecnica":"Decretada pelo Presidente; o Congresso aprecia o decreto em 24 horas, salvo quando dispensado. Durante a intervenção a CF não pode ser emendada.","dispositivo":"CF, arts. 34 a 36","tags":["federação"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Organização político-administrativa: União, Estados, DF, Municípios e Territórios"]]},{"termo":"Cargo em comissão","extenso":"Cargo de livre nomeação e exoneração","pratica":"Cargo de confiança, preenchido por escolha da autoridade, para direção, chefia e assessoramento.","tecnica":"Função de confiança é exclusiva de servidores efetivos; cargo em comissão tem percentual mínimo reservado a servidores de carreira.","dispositivo":"CF, art. 37, V","tags":["cargos"],"materias":["Noções de Direito Constitucional","Noções de Direito Administrativo"],"topicos":[["Noções de Direito Constitucional","Administração pública: disposições gerais"],["Noções de Direito Administrativo","Agentes públicos"]]},{"termo":"Validade do concurso","extenso":"Prazo do concurso público","pratica":"O concurso vale por até 2 anos, prorrogável uma vez por igual período.","tecnica":"Durante o prazo improrrogável, o aprovado tem prioridade sobre novos concursados. Aprovado dentro das vagas tem direito à nomeação (STF).","dispositivo":"CF, art. 37, III e IV","tags":["concurso"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Administração pública: disposições gerais"]]},{"termo":"Aposentadoria compulsória","extenso":"Aposentadoria por idade máxima","pratica":"O servidor é aposentado obrigatoriamente aos 75 anos, com proventos proporcionais ao tempo de contribuição.","tecnica":"CF, art. 40, § 1º, II, e LC 152/2015. Vale também para magistrados.","dispositivo":"CF, art. 40, § 1º, II","tags":["servidores"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Estabilidade do servidor","extenso":"Garantia de permanência","pratica":"Após 3 anos de efetivo exercício e avaliação especial de desempenho, o servidor efetivo fica estável.","tecnica":"Só perde o cargo por sentença transitada em julgado, PAD com ampla defesa, avaliação periódica insuficiente (lei complementar) ou excesso de despesa com pessoal.","dispositivo":"CF, art. 41","tags":["servidores"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Servidores públicos"]]},{"termo":"Garantias do Judiciário","extenso":"Autonomia administrativa e financeira","pratica":"Os tribunais têm autogoverno: elegem dirigentes, fazem regimentos e propõem seus orçamentos.","tecnica":"CF, arts. 96 e 99. Diferem das garantias dos magistrados (vitaliciedade, inamovibilidade e irredutibilidade de subsídio).","dispositivo":"CF, art. 99","tags":["Judiciário"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"]]},{"termo":"Inamovibilidade","extenso":"Garantia do juiz de não ser removido","pratica":"O juiz não pode ser removido contra a vontade, salvo por interesse público.","tecnica":"Remoção compulsória exige voto da maioria absoluta do tribunal ou do CNJ, com ampla defesa.","dispositivo":"CF, art. 95, II, e 93, VIII","tags":["garantias"],"materias":["Noções de Direito Constitucional","Lei de Organização Judiciária do DF e dos Territórios"],"topicos":[["Noções de Direito Constitucional","Poder Judiciário: disposições gerais"],["Lei de Organização Judiciária do DF e dos Territórios","Juízes de Direito e Juízes de Direito Substitutos"]]},{"termo":"Competência do STJ","extenso":"Uniformização da lei federal","pratica":"Julga o recurso especial e protege a interpretação da legislação federal infraconstitucional.","tecnica":"Também julga homologação de sentença estrangeira e exequatur de cartas rogatórias (CF, art. 105, I, i). Governadores respondem por crime comum no STJ.","dispositivo":"CF, art. 105","tags":["competência"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Órgãos do Poder Judiciário e competências"]]},{"termo":"Composição do CNJ","extenso":"Membros do Conselho Nacional de Justiça","pratica":"15 membros, com mandato de 2 anos, admitida uma recondução; presidido pelo Presidente do STF.","tecnica":"O Corregedor Nacional é o Ministro do STJ. O CNJ controla a atuação administrativa e financeira do Judiciário e não tem função jurisdicional; não tem competência sobre o STF.","dispositivo":"CF, art. 103-B","tags":["CNJ"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Conselho Nacional de Justiça: composição e competência"]]},{"termo":"Princípios institucionais do MP","extenso":"Unidade, indivisibilidade e independência funcional","pratica":"O MP é uma só instituição, seus membros podem se substituir e cada um atua com independência.","tecnica":"CF, art. 127, § 1º. Garantias dos membros: vitaliciedade, inamovibilidade e irredutibilidade de subsídio.","dispositivo":"CF, art. 127","tags":["MP"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: Ministério Público"]]},{"termo":"Defensoria Pública","extenso":"Assistência jurídica aos necessitados","pratica":"Instituição que presta orientação jurídica e defesa gratuita a quem não pode pagar advogado.","tecnica":"Tem autonomia funcional e administrativa. Princípios: unidade, indivisibilidade e independência funcional. Defensores não podem advogar fora das atribuições.","dispositivo":"CF, art. 134","tags":["Defensoria"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: advocacia e Defensoria Pública"]]},{"termo":"Advocacia","extenso":"Função essencial à Justiça","pratica":"O advogado é indispensável à administração da Justiça e inviolável por seus atos e manifestações no exercício da profissão, nos limites da lei.","tecnica":"CF, art. 133. Há exceções à indispensabilidade, como habeas corpus e Juizados Especiais até 20 salários mínimos.","dispositivo":"CF, art. 133","tags":["advocacia"],"materias":["Noções de Direito Constitucional"],"topicos":[["Noções de Direito Constitucional","Funções essenciais à Justiça: advocacia e Defensoria Pública"]]},{"termo":"Agência reguladora","extenso":"Autarquia em regime especial","pratica":"Autarquia que regula e fiscaliza setores (energia, telecomunicações, saúde), com maior autonomia.","tecnica":"Dirigentes com mandato fixo, nomeados após aprovação do Senado. Lei 13.848/2019.","dispositivo":null,"tags":["administração indireta"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Consórcio público","extenso":"Associação entre entes federativos","pratica":"União de entes (municípios, estados) para gerir serviços em conjunto.","tecnica":"Pode ser de direito público (associação pública, integra a administração indireta de todos) ou privado. Lei 11.107/2005.","dispositivo":null,"tags":["administração indireta"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Terceiro setor","extenso":"Entidades paraestatais","pratica":"Entidades privadas sem fins lucrativos que colaboram com o Estado: Sistema S, OS, OSCIP.","tecnica":"Não integram a administração indireta. Recebem recursos públicos e se submetem ao controle do Tribunal de Contas.","dispositivo":null,"tags":["terceiro setor"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Supremacia do interesse público","extenso":"Princípio implícito","pratica":"O interesse da coletividade prevalece sobre o particular.","tecnica":"Junto da indisponibilidade do interesse público forma o regime jurídico-administrativo. Fundamenta prerrogativas como as cláusulas exorbitantes.","dispositivo":null,"tags":["princípios"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"]]},{"termo":"Indisponibilidade do interesse público","extenso":"Princípio implícito","pratica":"O administrador não é dono do interesse público e não pode dispor dele livremente.","tecnica":"Limita as prerrogativas: exige licitação, concurso, motivação. Par da supremacia do interesse público.","dispositivo":null,"tags":["princípios"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"]]},{"termo":"Razoabilidade e proporcionalidade","extenso":"Princípios implícitos","pratica":"O ato deve ser adequado, necessário e equilibrado em relação ao fim buscado.","tecnica":"Lei 9.784, art. 2º, os prevê expressamente. Proíbem obrigações, restrições e sanções em medida superior à necessária.","dispositivo":"Lei 9.784/1999, art. 2º, VI","tags":["princípios"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"],["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Segurança jurídica","extenso":"Princípio da estabilidade","pratica":"Protege a confiança do cidadão e a estabilidade das relações.","tecnica":"Lei 9.784, art. 2º, XIII: veda a aplicação retroativa de nova interpretação. Fundamenta o prazo decadencial de 5 anos para anular atos favoráveis.","dispositivo":null,"tags":["princípios"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Princípios expressos e implícitos da administração pública"],["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Órgão independente","extenso":"Classificação dos órgãos","pratica":"Órgão previsto na CF, no topo da hierarquia, sem subordinação: Presidência, Casas Legislativas, Tribunais, MP.","tecnica":"Classificação de Hely Lopes Meirelles: independentes, autônomos (ministérios), superiores (secretarias, gabinetes) e subalternos (execução).","dispositivo":null,"tags":["órgãos"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Órgãos públicos"]]},{"termo":"Capacidade processual do órgão","extenso":"Órgão em juízo","pratica":"Órgão não tem personalidade jurídica, mas alguns podem defender suas prerrogativas em juízo.","tecnica":"Órgãos independentes e autônomos podem impetrar MS para proteger suas competências (ex.: Câmara Municipal).","dispositivo":null,"tags":["órgãos"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Órgãos públicos"]]},{"termo":"Agente político","extenso":"Agente com função de governo","pratica":"Ocupa cargos de cúpula previstos na CF: chefes do Executivo, parlamentares, ministros, secretários; para parte da doutrina, magistrados e membros do MP.","tecnica":"Regime próprio, sem a Lei 8.112. Diferem dos servidores públicos em sentido estrito.","dispositivo":null,"tags":["agentes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Agentes públicos"]]},{"termo":"Particular em colaboração","extenso":"Agente honorífico ou delegado","pratica":"Pessoa que, sem ser servidor, exerce função pública: jurado, mesário, concessionário, tabelião.","tecnica":"É agente público para fins de responsabilidade, inclusive penal (funcionário público por equiparação no que couber).","dispositivo":null,"tags":["agentes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Agentes públicos"]]},{"termo":"Nomeação","extenso":"Forma de provimento originário","pratica":"Ato que dá início à relação do servidor com o cargo.","tecnica":"Lei 8.112, art. 8º: formas de provimento são nomeação, promoção, readaptação, reversão, aproveitamento, reintegração e recondução. Só a nomeação é originária.","dispositivo":"Lei 8.112/1990, art. 8º","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Reintegração","extenso":"Retorno do servidor demitido ilegalmente","pratica":"Volta do servidor estável ao cargo quando a demissão é anulada, com ressarcimento de todas as vantagens.","tecnica":"Se o cargo foi extinto, fica em disponibilidade. O ocupante da vaga é reconduzido ao cargo de origem.","dispositivo":"Lei 8.112/1990, art. 28","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Recondução","extenso":"Retorno ao cargo anterior","pratica":"Volta do servidor estável ao cargo anterior por inabilitação no estágio de outro cargo ou por reintegração do anterior ocupante.","tecnica":"Lei 8.112, art. 29. O STF admite a recondução por desistência do estágio probatório no novo cargo.","dispositivo":"Lei 8.112/1990, art. 29","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Reversão","extenso":"Retorno do aposentado","pratica":"Volta do aposentado à atividade: por invalidez, quando cessam os motivos, ou no interesse da administração, a pedido.","tecnica":"Lei 8.112, art. 25. No interesse da administração exige pedido, aposentadoria voluntária, estabilidade anterior, aposentadoria há menos de 5 anos e cargo vago.","dispositivo":"Lei 8.112/1990, art. 25","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Aproveitamento","extenso":"Retorno do servidor em disponibilidade","pratica":"O servidor em disponibilidade volta à atividade em cargo de atribuições e vencimentos compatíveis com o anterior.","tecnica":"Obrigatório. Se o servidor não entrar em exercício no prazo, o aproveitamento fica sem efeito e a disponibilidade é cassada, salvo doença comprovada.","dispositivo":"Lei 8.112/1990, arts. 30 a 32","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Readaptação","extenso":"Provimento por limitação de saúde","pratica":"O servidor passa a ocupar cargo compatível com limitação física ou mental verificada em inspeção médica.","tecnica":"Lei 8.112, art. 24. Se julgado incapaz para o serviço público, é aposentado.","dispositivo":"Lei 8.112/1990, art. 24","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Exercício","extenso":"Início do desempenho do cargo","pratica":"Efetivo desempenho das atribuições do cargo.","tecnica":"Prazo de 15 dias contados da posse (Lei 8.112, art. 15). Se não entrar em exercício, o servidor é exonerado; se não tomar posse em 30 dias, a nomeação fica sem efeito.","dispositivo":"Lei 8.112/1990, art. 15","tags":["provimento"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Licença por motivo de doença em pessoa da família","extenso":"Licença da Lei 8.112","pratica":"Licença para acompanhar cônjuge, pais, filhos, padrasto ou madrasta, enteado ou dependente doente.","tecnica":"Lei 8.112, art. 83: até 60 dias com remuneração e mais até 90 dias sem remuneração, a cada 12 meses.","dispositivo":"Lei 8.112/1990, art. 83","tags":["licenças"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Licença para capacitação","extenso":"Licença da Lei 8.112","pratica":"Após cada quinquênio de efetivo exercício, até 3 meses de licença remunerada para curso de capacitação.","tecnica":"Lei 8.112, art. 87. Os períodos não são acumuláveis.","dispositivo":"Lei 8.112/1990, art. 87","tags":["licenças"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Lei 8.112/1990: regime jurídico dos servidores"]]},{"termo":"Silêncio administrativo","extenso":"Omissão da administração","pratica":"Quando a administração não responde a um pedido no prazo.","tecnica":"Lei 9.784, art. 49: concluída a instrução, a administração decide em até 30 dias, prorrogáveis por mais 30 motivadamente. O silêncio só produz efeito se a lei disser.","dispositivo":"Lei 9.784/1999, art. 49","tags":["processo administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Prazo de recurso administrativo","extenso":"Recurso na Lei 9.784","pratica":"O interessado tem 10 dias para recorrer, contados da ciência ou da divulgação da decisão.","tecnica":"Dirigido à autoridade que decidiu, que pode reconsiderar em 5 dias; tramita por no máximo 3 instâncias. Decisão do recurso em 30 dias.","dispositivo":"Lei 9.784/1999, arts. 56, 57 e 59","tags":["processo administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Reformatio in pejus","extenso":"Agravamento da situação do recorrente","pratica":"Decisão do recurso que piora a situação de quem recorreu.","tecnica":"Na Lei 9.784 (art. 64), o recurso pode agravar, desde que o recorrente seja avisado para se manifestar antes. Na revisão, não pode agravar a sanção (art. 65).","dispositivo":"Lei 9.784/1999, arts. 64 e 65","tags":["processo administrativo"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Processo administrativo: Lei 9.784/1999"]]},{"termo":"Poder vinculado","extenso":"Atuação sem margem de escolha","pratica":"A lei define todos os elementos do ato; a administração só pode agir daquele jeito.","tecnica":"Contrasta com o poder discricionário, em que há escolha por conveniência e oportunidade (mérito) dentro da lei.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"]]},{"termo":"Poder discricionário","extenso":"Margem de escolha do administrador","pratica":"A lei deixa ao administrador escolher, dentro de limites, a melhor solução por conveniência e oportunidade.","tecnica":"O mérito administrativo não é revisto pelo Judiciário, que controla apenas a legalidade, a razoabilidade e a proporcionalidade.","dispositivo":null,"tags":["poderes"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Poderes administrativos"],["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Mérito administrativo","extenso":"Conveniência e oportunidade","pratica":"Juízo de escolha do administrador nos atos discricionários, situado no motivo e no objeto.","tecnica":"O Judiciário não substitui esse juízo; a administração pode revogar o ato por mérito, com efeitos ex nunc.","dispositivo":null,"tags":["ato"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"],["Noções de Direito Administrativo","Controle administrativo, judicial e legislativo"]]},{"termo":"Cassação do ato","extenso":"Extinção por descumprimento","pratica":"Extinção do ato porque o beneficiário deixou de cumprir as condições exigidas.","tecnica":"Ex.: licença cassada por descumprimento das regras. Diferente de anulação (ilegalidade) e revogação (mérito).","dispositivo":null,"tags":["ato"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Ato administrativo"]]},{"termo":"Controle legislativo","extenso":"Controle exercido pelo Parlamento","pratica":"O Legislativo fiscaliza o Executivo: CPIs, sustação de atos normativos que exorbitem o poder regulamentar, julgamento das contas.","tecnica":"Controle político e financeiro (este com auxílio do Tribunal de Contas). CF, art. 49, V e X.","dispositivo":"CF, art. 49","tags":["controle"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Controle administrativo, judicial e legislativo"]]},{"termo":"Controle judicial","extenso":"Controle feito pelo Judiciário","pratica":"O Judiciário anula atos ilegais da administração, quando provocado.","tecnica":"Controla a legalidade e a legitimidade, não o mérito. Instrumentos: MS, ação popular, ação civil pública, HD.","dispositivo":null,"tags":["controle"],"materias":["Noções de Direito Administrativo","Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Administrativo","Controle administrativo, judicial e legislativo"],["Noções de Direito Processual Civil","Controle judicial dos atos administrativos e mandado de segurança"]]},{"termo":"Controle interno","extenso":"Controle dentro do próprio Poder","pratica":"Cada Poder mantém sistema que fiscaliza seus próprios atos.","tecnica":"Quem toma conhecimento de irregularidade deve informar o Tribunal de Contas, sob pena de responsabilidade solidária (CF, art. 74, § 1º).","dispositivo":"CF, art. 74","tags":["controle"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Controle administrativo, judicial e legislativo"],["Noções de Direito Administrativo","Controle pelos Tribunais de Contas"]]},{"termo":"Julgamento de contas","extenso":"Competência do Tribunal de Contas","pratica":"O Tribunal de Contas julga as contas de administradores e responsáveis por dinheiro público.","tecnica":"Exceção: as contas do chefe do Executivo são apenas analisadas por parecer prévio; o julgamento é do Legislativo (CF, art. 71, I e II).","dispositivo":"CF, art. 71","tags":["controle"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Controle pelos Tribunais de Contas"]]},{"termo":"Teoria do risco administrativo","extenso":"Base da responsabilidade objetiva","pratica":"O Estado responde pelo dano causado por seus agentes, independentemente de culpa, mas admite excludentes.","tecnica":"Excludentes: culpa exclusiva da vítima, caso fortuito ou força maior, fato de terceiro. A teoria do risco integral não admite excludentes (dano nuclear, ambiental).","dispositivo":"CF, art. 37, § 6º","tags":["responsabilidade"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Responsabilidade civil do Estado"]]},{"termo":"Omissão do Estado","extenso":"Responsabilidade por não agir","pratica":"Quando o dano decorre de omissão genérica, a doutrina tradicional exige culpa do serviço (responsabilidade subjetiva).","tecnica":"STF: se o Estado tinha dever específico de agir (ex.: preso sob custódia), a responsabilidade é objetiva.","dispositivo":null,"tags":["responsabilidade"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Responsabilidade civil do Estado"]]},{"termo":"Dupla garantia","extenso":"Ação contra o Estado, não contra o agente","pratica":"A vítima deve processar o Estado; o agente só responde depois, em ação regressiva, se agiu com dolo ou culpa.","tecnica":"Tese do STF (Tema 940): a ação deve ser ajuizada contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público.","dispositivo":null,"tags":["responsabilidade"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Responsabilidade civil do Estado"]]},{"termo":"Contratação direta","extenso":"Contratação sem licitação","pratica":"Contratação feita por dispensa ou inexigibilidade, com processo próprio de justificativa.","tecnica":"Lei 14.133, art. 72: exige documento de formalização da demanda, estimativa de despesa, parecer jurídico, comprovação de recursos, razão da escolha e justificativa do preço.","dispositivo":"Lei 14.133/2021, art. 72","tags":["licitação"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Sistema de registro de preços","extenso":"SRP","pratica":"Registro formal de preços para contratações futuras, sem obrigação de comprar.","tecnica":"Gera a ata de registro de preços, com vigência de 1 ano, prorrogável por igual período se o preço for vantajoso (Lei 14.133, art. 84).","dispositivo":"Lei 14.133/2021, arts. 82 a 86","tags":["licitação"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Pregão (Lei 10.520)","extenso":"Pregão na lei antiga","pratica":"Modalidade para bens e serviços comuns, com lances verbais e inversão de fases (julgamento antes da habilitação).","tecnica":"Revogada pela Lei 14.133 (desde 30/12/2023), mas ainda cobrada para contratos firmados sob ela. Hoje, o pregão está na própria Lei 14.133.","dispositivo":null,"tags":["licitação"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Leis 8.666/1993 e 10.520/2002"]]},{"termo":"Tomada de preços","extenso":"Modalidade da Lei 8.666","pratica":"Modalidade da lei antiga, entre interessados cadastrados ou que atendessem às condições até o 3º dia antes das propostas.","tecnica":"Extinta pela Lei 14.133, assim como o convite. A nova lei mantém concorrência, concurso, leilão, pregão e cria o diálogo competitivo.","dispositivo":null,"tags":["licitação"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Leis 8.666/1993 e 10.520/2002"]]},{"termo":"Alteração unilateral do contrato","extenso":"Cláusula exorbitante","pratica":"A administração pode alterar o contrato sem concordância do contratado, dentro de limites.","tecnica":"Lei 14.133, art. 125: acréscimos ou supressões de até 25% do valor (50% para reforma de edifício ou equipamento, só acréscimos). Mantém-se o equilíbrio econômico-financeiro.","dispositivo":"Lei 14.133/2021, arts. 104 e 125","tags":["contratos"],"materias":["Noções de Direito Administrativo"],"topicos":[["Noções de Direito Administrativo","Licitações e contratos: Lei 14.133/2021"]]},{"termo":"Analogia","extenso":"Integração por semelhança","pratica":"Na falta de lei, aplica-se a regra prevista para um caso parecido.","tecnica":"LINDB, art. 4º: na omissão da lei, o juiz decide pela analogia, pelos costumes e pelos princípios gerais de direito, nessa ordem tradicional. No direito penal, só a analogia em favor do réu.","dispositivo":"LINDB, art. 4º","tags":["integração"],"materias":["Noções de Direito Civil","Noções de Direito Penal"],"topicos":[["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"],["Noções de Direito Penal","Interpretação da lei penal, analogia e irretroatividade"]]},{"termo":"Ato jurídico perfeito","extenso":"Ato consumado segundo a lei da época","pratica":"Ato já concluído segundo a lei vigente quando foi praticado; a lei nova não pode atingi-lo.","tecnica":"Junto do direito adquirido e da coisa julgada, é protegido contra a retroatividade (CF, art. 5º, XXXVI; LINDB, art. 6º).","dispositivo":"LINDB, art. 6º","tags":["direito intertemporal"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Conflito das leis no tempo e eficácia da lei no espaço"],["Noções de Direito Civil","LINDB: vigência, aplicação, interpretação e integração das leis"]]},{"termo":"Lex loci","extenso":"Lei do lugar","pratica":"Regras da LINDB sobre qual lei aplicar em situações com elemento estrangeiro.","tecnica":"Capacidade, nome e direitos de família: lei do domicílio da pessoa (art. 7º). Bens: lei do lugar em que estão (art. 8º). Obrigações: lei do lugar onde se constituíram (art. 9º).","dispositivo":"LINDB, arts. 7º a 9º","tags":["direito internacional privado"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Conflito das leis no tempo e eficácia da lei no espaço"]]},{"termo":"Início da personalidade","extenso":"Nascimento com vida","pratica":"A pessoa adquire personalidade ao nascer com vida; o nascituro tem direitos resguardados desde a concepção.","tecnica":"CC, art. 2º. Basta respirar: não se exige viabilidade nem forma humana.","dispositivo":"CC, art. 2º","tags":["personalidade"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Morte presumida","extenso":"Morte declarada sem cadáver","pratica":"A morte é presumida nos casos de ausência com sucessão definitiva ou, sem ausência, quando for extremamente provável (perigo de vida, guerra).","tecnica":"CC, arts. 6º e 7º. No art. 7º, a sentença fixa a data provável do falecimento, depois de esgotadas as buscas.","dispositivo":"CC, arts. 6º e 7º","tags":["personalidade"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Ausência","extenso":"Desaparecimento sem notícia","pratica":"Pessoa que desaparece do domicílio sem deixar notícia nem representante.","tecnica":"Três fases: curadoria dos bens, sucessão provisória e sucessão definitiva (10 anos após a provisória, ou 5 anos de notícias se o ausente tiver 80 anos).","dispositivo":"CC, arts. 22 a 39","tags":["ausência"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas naturais: personalidade e capacidade"]]},{"termo":"Estado da pessoa","extenso":"Situação jurídica da pessoa","pratica":"Posição da pessoa na sociedade: estado político (nacional/estrangeiro), familiar (casado, solteiro, parente) e individual (idade, sexo, capacidade).","tecnica":"É indisponível, imprescritível e indivisível. Ações de estado são imprescritíveis.","dispositivo":null,"tags":["estado"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Nome, estado e domicílio da pessoa natural"]]},{"termo":"Domicílio necessário","extenso":"Domicílio fixado pela lei","pratica":"Algumas pessoas têm domicílio definido por lei: incapaz, servidor público, militar, marítimo e preso.","tecnica":"CC, art. 76. Servidor público: lugar onde exerce permanentemente as funções. Preso: lugar onde cumpre a sentença.","dispositivo":"CC, art. 76","tags":["domicílio"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Nome, estado e domicílio da pessoa natural"]]},{"termo":"Pluralidade de domicílios","extenso":"Mais de um domicílio","pratica":"Se a pessoa tem várias residências onde vive alternadamente, qualquer delas é domicílio.","tecnica":"CC, art. 71. Quanto às relações profissionais, também é domicílio o lugar onde a profissão é exercida (art. 72).","dispositivo":"CC, arts. 71 e 72","tags":["domicílio"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Nome, estado e domicílio da pessoa natural"]]},{"termo":"Direito ao nome","extenso":"Direito da personalidade","pratica":"Toda pessoa tem direito ao nome, compreendidos o prenome e o sobrenome.","tecnica":"CC, art. 16. Sem autorização, não se pode usar o nome alheio em propaganda comercial (art. 18). O pseudônimo usado em atividade lícita tem a mesma proteção (art. 19).","dispositivo":"CC, arts. 16 a 19","tags":["personalidade"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Direitos da personalidade"],["Noções de Direito Civil","Nome, estado e domicílio da pessoa natural"]]},{"termo":"Disposição do próprio corpo","extenso":"Limite dos direitos da personalidade","pratica":"É proibido dispor do próprio corpo quando houver diminuição permanente da integridade física ou contrariar os bons costumes, salvo por exigência médica.","tecnica":"CC, art. 13. É permitida a disposição gratuita do corpo, no todo ou em parte, para depois da morte, com fins científicos ou altruísticos (art. 14), revogável a qualquer tempo.","dispositivo":"CC, arts. 13 e 14","tags":["personalidade"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Direitos da personalidade"]]},{"termo":"Pessoa jurídica de direito público","extenso":"PJ de direito público interno","pratica":"União, estados, DF, municípios, autarquias (incluídas as associações públicas) e demais entidades criadas por lei.","tecnica":"CC, art. 41. Respondem objetivamente pelos danos de seus agentes (art. 43).","dispositivo":"CC, art. 41","tags":["pessoa jurídica"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas jurídicas: disposições gerais e domicílio"]]},{"termo":"Início da pessoa jurídica de direito privado","extenso":"Registro do ato constitutivo","pratica":"A existência legal da PJ de direito privado começa com a inscrição do ato constitutivo no registro próprio.","tecnica":"CC, art. 45. Antes disso há sociedade em comum ou não personificada.","dispositivo":"CC, art. 45","tags":["pessoa jurídica"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Pessoas jurídicas: disposições gerais e domicílio"]]},{"termo":"Velamento das fundações","extenso":"Fiscalização pelo Ministério Público","pratica":"O MP do estado onde a fundação está acompanha e fiscaliza sua atuação.","tecnica":"CC, art. 66. No DF, cabe ao MPDFT. Fundação só pode ter fins religiosos, morais, culturais, de assistência e similares listados no art. 62.","dispositivo":"CC, art. 66","tags":["fundações"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Associações e fundações"]]},{"termo":"Exclusão de associado","extenso":"Saída forçada da associação","pratica":"O associado só pode ser excluído por justa causa, com procedimento que assegure defesa e recurso.","tecnica":"CC, art. 57. Associação não tem fins econômicos e entre os associados não há direitos e obrigações recíprocos (art. 53).","dispositivo":"CC, arts. 53 e 57","tags":["associações"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Associações e fundações"]]},{"termo":"Bens públicos de uso comum","extenso":"Bens do povo","pratica":"Bens usados por todos: rios, mares, estradas, ruas e praças.","tecnica":"Classificação do CC, art. 99: uso comum, uso especial (prédios de serviço) e dominicais (patrimônio disponível). Só os dominicais podem ser alienados, observada a lei.","dispositivo":"CC, art. 99","tags":["bens"],"materias":["Noções de Direito Civil","Noções de Direito Administrativo"],"topicos":[["Noções de Direito Civil","Bens"],["Noções de Direito Administrativo","Organização administrativa: administração direta e indireta"]]},{"termo":"Benfeitorias","extenso":"Melhorias feitas no bem","pratica":"Obras ou despesas feitas na coisa: necessárias (conservam), úteis (aumentam o uso) e voluptuárias (mero luxo).","tecnica":"CC, art. 96. São bens acessórios, ao lado de frutos e produtos. Pertenças não são partes integrantes.","dispositivo":"CC, art. 96","tags":["bens"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Bens"]]},{"termo":"Bens imóveis","extenso":"Bens que não se transportam sem destruição","pratica":"O solo e tudo o que nele se incorpora natural ou artificialmente.","tecnica":"CC, arts. 79 e 80: por lei também são imóveis os direitos reais sobre imóveis e o direito à sucessão aberta. Materiais provisoriamente separados de um prédio não perdem o caráter de imóveis.","dispositivo":"CC, arts. 79 a 81","tags":["bens"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Bens"]]},{"termo":"Negócio jurídico","extenso":"Declaração de vontade com efeitos queridos","pratica":"Ato em que as partes escolhem os efeitos que querem produzir, como o contrato.","tecnica":"Validade (CC, art. 104): agente capaz, objeto lícito, possível e determinado ou determinável, e forma prescrita ou não proibida em lei.","dispositivo":"CC, art. 104","tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Planos do negócio jurídico","extenso":"Escada ponteana","pratica":"Existência, validade e eficácia, analisados nessa ordem.","tecnica":"Existência: agente, vontade, objeto, forma. Validade: requisitos do art. 104. Eficácia: condição, termo e encargo.","dispositivo":null,"tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Condição","extenso":"Evento futuro e incerto","pratica":"Cláusula que faz o efeito do negócio depender de evento futuro e incerto.","tecnica":"Suspensiva: o direito só é adquirido quando o evento acontece. Resolutiva: o direito acaba quando ele acontece. Termo é evento futuro e certo.","dispositivo":"CC, arts. 121 a 130","tags":["negócio jurídico"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Erro","extenso":"Defeito do negócio jurídico","pratica":"A pessoa se engana sozinha sobre algo essencial do negócio.","tecnica":"Anulável se o erro for substancial e perceptível por pessoa de diligência normal. Dolo é o engano provocado pela outra parte.","dispositivo":"CC, arts. 138 a 144","tags":["defeitos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Coação","extenso":"Defeito do negócio jurídico","pratica":"Ameaça grave que força a pessoa a fazer o negócio.","tecnica":"Torna o negócio anulável (CC, art. 151). Temor reverencial (respeito aos pais, por exemplo) não é coação.","dispositivo":"CC, arts. 151 a 155","tags":["defeitos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Lesão","extenso":"Defeito do negócio jurídico","pratica":"Por necessidade ou inexperiência, a pessoa assume prestação desproporcional.","tecnica":"Anulável. Diferente do estado de perigo, em que a pessoa assume obrigação excessiva para salvar a si ou alguém de grave dano conhecido pela outra parte.","dispositivo":"CC, art. 157","tags":["defeitos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Simulação","extenso":"Negócio aparente","pratica":"As partes fingem um negócio que não querem de verdade.","tecnica":"É causa de nulidade (CC, art. 167), não de anulabilidade. Subsiste o negócio dissimulado se válido na substância e na forma.","dispositivo":"CC, art. 167","tags":["defeitos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Fraude contra credores","extenso":"Defeito social do negócio","pratica":"O devedor insolvente se desfaz de bens para não pagar os credores.","tecnica":"Anulável por ação pauliana, em 4 anos. Diferente da fraude à execução, que ocorre com processo em curso e gera ineficácia.","dispositivo":"CC, arts. 158 a 165","tags":["defeitos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Fatos jurídicos e negócio jurídico"]]},{"termo":"Abuso de direito","extenso":"Ato ilícito por excesso","pratica":"Exercer um direito excedendo os limites do seu fim econômico ou social, da boa-fé ou dos bons costumes.","tecnica":"CC, art. 187: é ato ilícito, e a responsabilidade é objetiva (Enunciado 37 CJF).","dispositivo":"CC, art. 187","tags":["ato ilícito"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Atos jurídicos lícitos e atos ilícitos"]]},{"termo":"Ato lícito","extenso":"Ato conforme o direito","pratica":"Ato que a lei permite e que não gera dever de indenizar, em regra.","tecnica":"CC, art. 188: não são ilícitos a legítima defesa, o exercício regular de direito e o estado de necessidade (com limites).","dispositivo":"CC, art. 188","tags":["atos"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Atos jurídicos lícitos e atos ilícitos"]]},{"termo":"Prazo prescricional geral","extenso":"Prescrição de 10 anos","pratica":"Quando a lei não fixa prazo menor, a prescrição ocorre em 10 anos.","tecnica":"CC, art. 205. Reparação civil: 3 anos (art. 206, § 3º, V).","dispositivo":"CC, arts. 205 e 206","tags":["prescrição"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Prescrição e decadência"]]},{"termo":"Interrupção da prescrição","extenso":"Prazo zera e recomeça","pratica":"Certos atos fazem a contagem da prescrição recomeçar do zero.","tecnica":"Só pode ocorrer uma vez (CC, art. 202). Ex.: despacho que ordena a citação, protesto, reconhecimento do direito pelo devedor. Suspensão apenas para a contagem, que depois continua de onde parou.","dispositivo":"CC, art. 202","tags":["prescrição"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Prescrição e decadência"]]},{"termo":"Causas impeditivas da prescrição","extenso":"Prazo que nem começa","pratica":"Situações em que a prescrição não corre: entre cônjuges na constância da sociedade conjugal, entre ascendentes e descendentes no poder familiar, contra absolutamente incapazes.","tecnica":"CC, arts. 197 e 198. Decadência legal não se suspende nem se interrompe, salvo contra absolutamente incapaz.","dispositivo":"CC, arts. 197 a 199","tags":["prescrição"],"materias":["Noções de Direito Civil"],"topicos":[["Noções de Direito Civil","Prescrição e decadência"]]},{"termo":"Interesse processual","extenso":"Interesse de agir","pratica":"A parte precisa do processo para obter o que quer, e o meio escolhido é adequado.","tecnica":"CPC, art. 17: para postular em juízo é necessário ter interesse e legitimidade. A falta gera extinção sem resolução do mérito.","dispositivo":"CPC, art. 17","tags":["ação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Ação: condições, elementos e classificação"]]},{"termo":"Legitimidade","extenso":"Legitimidade ad causam","pratica":"Pertinência subjetiva da ação: quem pede e contra quem se pede devem ser os titulares da relação discutida.","tecnica":"Regra: ninguém pode pleitear direito alheio em nome próprio, salvo quando autorizado pelo ordenamento (legitimação extraordinária, art. 18).","dispositivo":"CPC, arts. 17 e 18","tags":["ação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Ação: condições, elementos e classificação"]]},{"termo":"Elementos da ação","extenso":"Partes, pedido e causa de pedir","pratica":"Os três elementos que identificam uma ação.","tecnica":"Duas ações com os três elementos iguais são idênticas (litispendência ou coisa julgada). Conexão: mesmo pedido ou causa de pedir.","dispositivo":"CPC, art. 337, § 2º","tags":["ação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Ação: condições, elementos e classificação"]]},{"termo":"Litispendência","extenso":"Ação idêntica em curso","pratica":"Repetição de ação que ainda está em andamento.","tecnica":"Gera extinção sem resolução do mérito do segundo processo. Coisa julgada: repetição de ação já decidida por decisão transitada.","dispositivo":"CPC, art. 337, §§ 1º a 3º","tags":["ação"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Ação: condições, elementos e classificação"],["Noções de Direito Processual Civil","Pressupostos processuais e preclusão"]]},{"termo":"Capacidade postulatória","extenso":"Capacidade de pedir em juízo","pratica":"Aptidão técnica para praticar atos no processo, em regra exclusiva do advogado.","tecnica":"Exceções: Juizados Especiais até 20 salários mínimos, habeas corpus, Justiça do Trabalho. Defensoria e MP têm capacidade própria.","dispositivo":"CPC, art. 103","tags":["sujeitos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sujeitos do processo: capacidade processual e postulatória"]]},{"termo":"Capacidade processual","extenso":"Capacidade de estar em juízo","pratica":"Aptidão para praticar atos processuais por si; os incapazes são representados ou assistidos.","tecnica":"CPC, art. 70. O juiz, verificando incapacidade, suspende o processo e dá prazo para corrigir (art. 76).","dispositivo":"CPC, arts. 70 e 76","tags":["sujeitos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sujeitos do processo: capacidade processual e postulatória"]]},{"termo":"Curador especial","extenso":"Defensor nomeado pelo juiz","pratica":"Representante nomeado para o incapaz sem representante e para o réu preso revel ou citado por edital ou hora certa que fique revel.","tecnica":"CPC, art. 72. A função é exercida pela Defensoria Pública.","dispositivo":"CPC, art. 72","tags":["sujeitos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Sujeitos do processo: capacidade processual e postulatória"]]},{"termo":"Litigância de má-fé","extenso":"Abuso no processo","pratica":"Comportamento desleal da parte: alterar a verdade, usar o processo para fim ilegal, recorrer só para atrasar.","tecnica":"Multa superior a 1% e inferior a 10% do valor corrigido da causa, além de indenização e honorários (CPC, art. 81).","dispositivo":"CPC, arts. 80 e 81","tags":["deveres"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Deveres das partes e procuradores; sucessão e substituição"]]},{"termo":"Ato atentatório à dignidade da justiça","extenso":"Desobediência às decisões","pratica":"Descumprir decisões ou criar embaraços à sua efetivação.","tecnica":"Multa de até 20% do valor da causa, revertida ao Estado (CPC, art. 77, § 2º). Não se aplica aos advogados, que respondem perante a OAB.","dispositivo":"CPC, art. 77","tags":["deveres"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Deveres das partes e procuradores; sucessão e substituição"]]},{"termo":"Sucessão processual","extenso":"Troca de parte no processo","pratica":"Uma pessoa assume o lugar da parte no processo, como os herdeiros após a morte.","tecnica":"Alienação da coisa litigiosa não altera a legitimidade; o adquirente só sucede com consentimento da parte contrária (CPC, art. 109).","dispositivo":"CPC, arts. 108 a 112","tags":["sujeitos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Deveres das partes e procuradores; sucessão e substituição"]]},{"termo":"Perito","extenso":"Auxiliar técnico do juiz","pratica":"Especialista nomeado para esclarecer fatos que dependem de conhecimento técnico.","tecnica":"Escolhido entre profissionais inscritos em cadastro do tribunal (CPC, art. 156). As partes podem escolher consensualmente o perito (art. 471).","dispositivo":"CPC, art. 156","tags":["auxiliares"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Auxiliares da Justiça"],["Noções de Direito Processual Civil","Audiência de instrução e julgamento e provas"]]},{"termo":"Escrivão ou chefe de secretaria","extenso":"Auxiliar da Justiça","pratica":"Responsável pela documentação dos atos do processo, guarda dos autos e redação de ofícios e mandados.","tecnica":"CPC, art. 152. Responde civil e regressivamente quando, sem justo motivo, se recusa a cumprir atos do juiz ou pratica ato nulo com dolo ou culpa.","dispositivo":"CPC, art. 152","tags":["auxiliares"],"materias":["Noções de Direito Processual Civil","Provimento Geral da Corregedoria"],"topicos":[["Noções de Direito Processual Civil","Auxiliares da Justiça"],["Provimento Geral da Corregedoria","Atribuições dos ofícios judiciais: autuação, juntada, certidões e conclusão"]]},{"termo":"Conciliador e mediador","extenso":"Auxiliares da autocomposição","pratica":"Conciliador sugere soluções em casos sem vínculo anterior; mediador ajuda partes com vínculo a restabelecer o diálogo.","tecnica":"CPC, art. 165, §§ 2º e 3º. Princípios: independência, imparcialidade, autonomia da vontade, confidencialidade, oralidade, informalidade e decisão informada.","dispositivo":"CPC, art. 165","tags":["autocomposição"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Auxiliares da Justiça"],["Noções de Direito Processual Civil","Audiência de conciliação ou de mediação"]]},{"termo":"Nulidade relativa","extenso":"Vício sanável","pratica":"Defeito que só é declarado se a parte prejudicada alegar na primeira oportunidade.","tecnica":"Não se declara nulidade sem prejuízo, nem a pedido de quem lhe deu causa (CPC, arts. 276 e 282). Absoluta: pode ser reconhecida de ofício.","dispositivo":"CPC, arts. 276 a 283","tags":["nulidades"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Nulidades"]]},{"termo":"Instrumentalidade das formas","extenso":"Aproveitamento do ato","pratica":"Se o ato atingiu sua finalidade, ainda que de outro modo, é válido.","tecnica":"CPC, art. 277. Base da regra de que não há nulidade sem prejuízo (pas de nullité sans grief).","dispositivo":"CPC, art. 277","tags":["nulidades"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Nulidades"],["Noções de Direito Processual Civil","Atos processuais: forma, tempo, lugar e prazos"]]},{"termo":"Valor da causa","extenso":"Valor atribuído à ação","pratica":"Toda causa recebe um valor certo, ainda que sem conteúdo econômico imediato.","tecnica":"CPC, art. 291. Serve para custas, competência dos Juizados e multas. O juiz pode corrigi-lo de ofício (art. 292, § 3º).","dispositivo":"CPC, arts. 291 e 292","tags":["valor da causa"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Distribuição, registro e valor da causa"]]},{"termo":"Requisitos da petição inicial","extenso":"O que a inicial precisa ter","pratica":"Juízo, partes e qualificação, fatos e fundamentos jurídicos, pedido, valor da causa, provas e opção pela audiência de conciliação.","tecnica":"CPC, art. 319. Se faltar algo sanável, o juiz manda emendar em 15 dias antes de indeferir (art. 321).","dispositivo":"CPC, arts. 319 e 321","tags":["petição inicial"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Petição inicial, pedido, indeferimento e improcedência liminar"]]},{"termo":"Indeferimento da petição inicial","extenso":"Inicial rejeitada","pratica":"O juiz rejeita a inicial sem ouvir o réu por inépcia, ilegitimidade, falta de interesse ou não emenda.","tecnica":"CPC, art. 330. Cabe apelação, e o juiz pode se retratar em 5 dias (art. 331).","dispositivo":"CPC, arts. 330 e 331","tags":["petição inicial"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Petição inicial, pedido, indeferimento e improcedência liminar"]]},{"termo":"Improcedência liminar do pedido","extenso":"Julgamento de mérito antes da citação","pratica":"Nas causas sem necessidade de provas, o juiz julga improcedente o pedido que contraria súmula, recurso repetitivo, IRDR ou súmula de TJ sobre direito local.","tecnica":"CPC, art. 332. Também na prescrição ou decadência. Cabe apelação com retratação em 5 dias.","dispositivo":"CPC, art. 332","tags":["petição inicial"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Petição inicial, pedido, indeferimento e improcedência liminar"]]},{"termo":"Audiência de conciliação ou mediação","extenso":"Audiência inicial do procedimento comum","pratica":"Audiência para tentar o acordo antes da contestação.","tecnica":"CPC, art. 334: designada com antecedência mínima de 30 dias e citação do réu com pelo menos 20 dias. Só não ocorre se ambas as partes manifestarem desinteresse ou se não se admitir autocomposição. Ausência injustificada: multa de até 2%.","dispositivo":"CPC, art. 334","tags":["audiência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Audiência de conciliação ou de mediação"]]},{"termo":"Saneamento","extenso":"Decisão de organização do processo","pratica":"Decisão em que o juiz resolve questões pendentes, fixa os pontos controvertidos, distribui o ônus da prova e define as provas.","tecnica":"CPC, art. 357. As partes podem pedir esclarecimentos em 5 dias; em causas complexas, o saneamento pode ser feito em audiência.","dispositivo":"CPC, art. 357","tags":["saneamento"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Providências preliminares, saneamento e julgamento conforme o estado do processo"]]},{"termo":"Julgamento antecipado do mérito","extenso":"Sentença sem instrução","pratica":"O juiz julga logo quando não há necessidade de mais provas ou o réu é revel com efeitos da revelia.","tecnica":"CPC, art. 355. Julgamento antecipado parcial (art. 356) resolve parte do mérito incontroversa ou madura, por decisão agravável.","dispositivo":"CPC, arts. 355 e 356","tags":["julgamento"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Providências preliminares, saneamento e julgamento conforme o estado do processo"]]},{"termo":"Ônus da prova","extenso":"Quem deve provar","pratica":"Ao autor cabe provar o fato constitutivo do direito; ao réu, o fato impeditivo, modificativo ou extintivo.","tecnica":"CPC, art. 373. O juiz pode distribuir de modo diverso (carga dinâmica), por decisão fundamentada e dando à parte oportunidade de se desincumbir.","dispositivo":"CPC, art. 373","tags":["provas"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Audiência de instrução e julgamento e provas"]]},{"termo":"Prova testemunhal","extenso":"Depoimento de testemunhas","pratica":"Cada parte pode arrolar até 10 testemunhas, no máximo 3 para cada fato.","tecnica":"CPC, art. 357, § 6º. O advogado intima a própria testemunha (art. 455). Não podem depor incapazes, impedidos e suspeitos.","dispositivo":"CPC, arts. 357 e 455","tags":["provas"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Audiência de instrução e julgamento e provas"]]},{"termo":"Audiência de instrução e julgamento","extenso":"AIJ","pratica":"Audiência em que se colhem provas orais, há debates e o juiz pode sentenciar.","tecnica":"Ordem preferencial: perito, depoimento pessoal do autor e do réu, testemunhas do autor e do réu (CPC, art. 361). Debates de 20 minutos, prorrogáveis por 10.","dispositivo":"CPC, arts. 358 a 368","tags":["audiência"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Audiência de instrução e julgamento e provas"]]},{"termo":"Efeito devolutivo","extenso":"Transferência da matéria ao Tribunal","pratica":"O recurso devolve ao tribunal o conhecimento da matéria impugnada.","tecnica":"Todos os recursos têm. O efeito suspensivo impede a eficácia da decisão; a apelação tem, em regra, efeito suspensivo (CPC, art. 1.012).","dispositivo":null,"tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Prazo recursal","extenso":"Prazo de 15 dias úteis","pratica":"Em regra, os recursos do CPC têm prazo de 15 dias.","tecnica":"Exceção: embargos de declaração, 5 dias (CPC, art. 1.003, § 5º). MP, Fazenda e Defensoria têm prazo em dobro.","dispositivo":"CPC, art. 1.003, § 5º","tags":["recursos","prazos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Recurso adesivo","extenso":"Recurso subordinado","pratica":"Quando ambos perdem em parte, quem não recorreu pode aderir ao recurso da outra parte.","tecnica":"Cabe na apelação, no recurso especial e no extraordinário. Segue a sorte do principal: se este não for conhecido, o adesivo cai.","dispositivo":"CPC, art. 997","tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Princípio da dialeticidade","extenso":"Recurso precisa atacar a decisão","pratica":"O recorrente deve apontar os fundamentos de fato e de direito pelos quais a decisão está errada.","tecnica":"Recurso que não impugna especificamente os fundamentos da decisão não é conhecido (CPC, art. 932, III).","dispositivo":null,"tags":["recursos"],"materias":["Noções de Direito Processual Civil"],"topicos":[["Noções de Direito Processual Civil","Recursos: disposições gerais"]]},{"termo":"Pena cumprida no estrangeiro","extenso":"Detração e atenuação","pratica":"A pena cumprida no exterior atenua a imposta no Brasil pelo mesmo crime, quando diversas, ou nela é computada, quando idênticas.","tecnica":"CP, art. 8º. Evita punir duas vezes pelo mesmo fato.","dispositivo":"CP, art. 8º","tags":["extraterritorialidade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Pena cumprida no estrangeiro e eficácia da sentença estrangeira"]]},{"termo":"Homologação de sentença penal estrangeira","extenso":"Eficácia da sentença estrangeira","pratica":"A sentença penal estrangeira pode produzir no Brasil certos efeitos, após homologação pelo STJ.","tecnica":"CP, art. 9º: obrigar à reparação do dano e a outros efeitos civis, ou sujeitar a medida de segurança. Para reincidência, não é preciso homologar.","dispositivo":"CP, art. 9º","tags":["sentença estrangeira"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Pena cumprida no estrangeiro e eficácia da sentença estrangeira"]]},{"termo":"Contagem de prazo penal","extenso":"Inclui o dia do começo","pratica":"No prazo penal, o dia do começo conta.","tecnica":"CP, art. 10: dias, meses e anos pelo calendário comum. Prazo processual penal (CPP, art. 798) exclui o dia do começo.","dispositivo":"CP, art. 10","tags":["prazos"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Contagem de prazo e frações não computáveis da pena"]]},{"termo":"Frações não computáveis","extenso":"Desprezo de frações da pena","pratica":"Na pena privativa de liberdade e na restritiva de direitos desprezam-se as frações de dia; na multa, as frações de real.","tecnica":"CP, art. 11.","dispositivo":"CP, art. 11","tags":["pena"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Contagem de prazo e frações não computáveis da pena"]]},{"termo":"Princípio da especialidade","extenso":"Conflito aparente de normas","pratica":"A norma especial prevalece sobre a geral.","tecnica":"Ex.: infanticídio prevalece sobre homicídio. Os outros princípios são subsidiariedade, consunção e alternatividade.","dispositivo":null,"tags":["conflito aparente"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Conflito aparente de normas penais"]]},{"termo":"Princípio da subsidiariedade","extenso":"Conflito aparente de normas","pratica":"A norma principal afasta a subsidiária, que só se aplica se a principal não incidir.","tecnica":"Pode ser expressa (“se o fato não constitui crime mais grave”) ou tácita.","dispositivo":null,"tags":["conflito aparente"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Conflito aparente de normas penais"]]},{"termo":"Princípio da consunção","extenso":"Absorção","pratica":"O crime-meio ou menos grave é absorvido pelo crime-fim.","tecnica":"Súmula 17 do STJ: o falso que se esgota no estelionato, sem mais potencialidade lesiva, é por este absorvido.","dispositivo":"Súmula 17 STJ","tags":["conflito aparente"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Conflito aparente de normas penais"]]},{"termo":"Crime doloso","extenso":"Dolo","pratica":"O agente quer o resultado (dolo direto) ou assume o risco de produzi-lo (dolo eventual).","tecnica":"CP, art. 18, I. A regra é punir só o crime doloso; o culposo exige previsão expressa.","dispositivo":"CP, art. 18","tags":["dolo"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Crime culposo","extenso":"Culpa","pratica":"O agente causa o resultado por imprudência, negligência ou imperícia.","tecnica":"Exige previsão legal. Culpa consciente: prevê o resultado mas acredita que não vai ocorrer (diferente do dolo eventual).","dispositivo":"CP, art. 18, II","tags":["culpa"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Tentativa","extenso":"Crime não consumado por circunstâncias alheias","pratica":"Começa a execução, mas o crime não se consuma por motivos alheios à vontade do agente.","tecnica":"CP, art. 14, II: pena do consumado reduzida de 1/3 a 2/3. Desistência voluntária e arrependimento eficaz: o agente responde só pelos atos já praticados.","dispositivo":"CP, art. 14","tags":["iter criminis"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Crime impossível","extenso":"Tentativa inidônea","pratica":"Não se pune a tentativa quando o meio é absolutamente ineficaz ou o objeto é absolutamente impróprio.","tecnica":"CP, art. 17. Súmula 145 do STF: não há crime quando a preparação do flagrante pela polícia torna impossível a consumação.","dispositivo":"CP, art. 17","tags":["iter criminis"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Teoria do crime: tipo penal objetivo e subjetivo"]]},{"termo":"Estrito cumprimento do dever legal","extenso":"Excludente de ilicitude","pratica":"O agente pratica fato típico cumprindo obrigação imposta por lei.","tecnica":"CP, art. 23, III. Ex.: policial que cumpre mandado de prisão. Junto do exercício regular de direito, legítima defesa e estado de necessidade.","dispositivo":"CP, art. 23","tags":["excludentes"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Ilicitude e causas excludentes"]]},{"termo":"Excesso punível","extenso":"Excesso nas excludentes","pratica":"Quem se excede em qualquer excludente de ilicitude responde pelo excesso doloso ou culposo.","tecnica":"CP, art. 23, parágrafo único.","dispositivo":"CP, art. 23, parágrafo único","tags":["excludentes"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Ilicitude e causas excludentes"]]},{"termo":"Coação moral irresistível","extenso":"Dirimente","pratica":"Quem age sob coação moral irresistível não é culpável; responde só o coator.","tecnica":"CP, art. 22, junto da obediência hierárquica a ordem não manifestamente ilegal. Coação física irresistível exclui a conduta (o próprio fato típico).","dispositivo":"CP, art. 22","tags":["dirimentes"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Culpabilidade e causas dirimentes"]]},{"termo":"Embriaguez","extenso":"Embriaguez e culpabilidade","pratica":"A embriaguez voluntária ou culposa não exclui a imputabilidade.","tecnica":"CP, art. 28. Só a completa, proveniente de caso fortuito ou força maior, isenta de pena. Emoção e paixão também não excluem a imputabilidade.","dispositivo":"CP, art. 28","tags":["imputabilidade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Culpabilidade e causas dirimentes"]]},{"termo":"Homicídio qualificado","extenso":"Homicídio com circunstâncias graves","pratica":"Homicídio por motivo torpe ou fútil, com meio cruel, emboscada, para assegurar outro crime, entre outros.","tecnica":"Pena de 12 a 30 anos. É hediondo. Feminicídio passou a ser crime autônomo (CP, art. 121-A, Lei 14.994/2024).","dispositivo":"CP, art. 121, § 2º","tags":["crimes contra a vida"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a pessoa"],["Noções de Direito Penal","Crimes hediondos (Lei 8.072/1990)"]]},{"termo":"Lesão corporal","extenso":"Ofensa à integridade ou à saúde","pratica":"Ofender a integridade corporal ou a saúde de outra pessoa.","tecnica":"Leve, grave (ex.: incapacidade por mais de 30 dias), gravíssima (ex.: perda de membro) ou seguida de morte. A leve e a culposa dependem de representação (Lei 9.099, art. 88), salvo violência doméstica contra a mulher.","dispositivo":"CP, art. 129","tags":["crimes contra a pessoa"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a pessoa"]]},{"termo":"Crimes contra a honra","extenso":"Calúnia, difamação e injúria","pratica":"Calúnia: imputar falsamente fato criminoso. Difamação: imputar fato ofensivo à reputação. Injúria: ofender a dignidade ou o decoro.","tecnica":"Calúnia e difamação atingem a honra objetiva; injúria, a subjetiva. Exceção da verdade cabe na calúnia e, na difamação, só contra funcionário público no exercício da função.","dispositivo":"CP, arts. 138 a 140","tags":["honra"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a pessoa"]]},{"termo":"Ameaça","extenso":"Crime contra a liberdade individual","pratica":"Ameaçar alguém de causar mal injusto e grave por palavra, escrito, gesto ou outro meio.","tecnica":"CP, art. 147: detenção de 1 a 6 meses ou multa; ação pública condicionada à representação.","dispositivo":"CP, art. 147","tags":["liberdade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a pessoa"]]},{"termo":"Apropriação indébita","extenso":"Crime contra o patrimônio","pratica":"Ficar com coisa alheia móvel que já estava na posse ou detenção do agente.","tecnica":"CP, art. 168. Diferente do furto (subtração) e do estelionato (a vítima entrega por engano provocado).","dispositivo":"CP, art. 168","tags":["patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Extorsão","extenso":"Crime contra o patrimônio","pratica":"Constranger alguém, com violência ou grave ameaça, a fazer, tolerar ou deixar de fazer algo para obter vantagem econômica.","tecnica":"No roubo, o agente subtrai; na extorsão, a colaboração da vítima é indispensável. Súmula 96 do STJ: crime formal, consuma-se independentemente da vantagem.","dispositivo":"CP, art. 158","tags":["patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Receptação","extenso":"Crime contra o patrimônio","pratica":"Adquirir, receber, transportar ou ocultar coisa que sabe ser produto de crime.","tecnica":"CP, art. 180. É punível ainda que desconhecido ou isento de pena o autor do crime anterior.","dispositivo":"CP, art. 180","tags":["patrimônio"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra o patrimônio"]]},{"termo":"Peculato culposo","extenso":"Peculato por negligência","pratica":"O funcionário, por culpa, concorre para que outro se aproprie ou desvie bem público.","tecnica":"CP, art. 312, § 3º. A reparação do dano antes da sentença irrecorrível extingue a punibilidade; depois, reduz a pena pela metade.","dispositivo":"CP, art. 312, §§ 2º e 3º","tags":["administração pública"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Excesso de exação","extenso":"Crime funcional","pratica":"Exigir tributo ou contribuição que sabe indevido, ou cobrar por meio vexatório ou gravoso.","tecnica":"CP, art. 316, § 1º. Modalidade especial da concussão.","dispositivo":"CP, art. 316, § 1º","tags":["administração pública"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Resistência","extenso":"Crime de particular contra a administração","pratica":"Opor-se à execução de ato legal, com violência ou ameaça, contra funcionário competente.","tecnica":"CP, art. 329. Desobediência (art. 330) é desobedecer ordem legal sem violência; desacato (art. 331) é ofender o funcionário no exercício da função.","dispositivo":"CP, art. 329","tags":["administração pública"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Desacato","extenso":"Crime contra a administração","pratica":"Desrespeitar funcionário público no exercício da função ou em razão dela.","tecnica":"CP, art. 331. O STF considerou o tipo compatível com a Constituição e com a Convenção Americana (ADPF 496).","dispositivo":"CP, art. 331","tags":["administração pública"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes contra a administração pública"]]},{"termo":"Mandado de criminalização","extenso":"Ordem constitucional de punir","pratica":"A CF manda o legislador punir certas condutas: racismo, tortura, tráfico, terrorismo, crimes hediondos, ação de grupos armados.","tecnica":"Racismo e ação de grupos armados contra a ordem democrática: inafiançáveis e imprescritíveis. Tortura, tráfico, terrorismo e hediondos: inafiançáveis e insuscetíveis de graça ou anistia.","dispositivo":"CF, art. 5º, XLII a XLIV","tags":["constituição"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Disposições constitucionais aplicáveis ao direito penal"]]},{"termo":"Penas proibidas","extenso":"Vedação constitucional","pratica":"A CF proíbe penas de morte (salvo guerra declarada), de caráter perpétuo, de trabalhos forçados, de banimento e cruéis.","tecnica":"CF, art. 5º, XLVII. É cláusula pétrea.","dispositivo":"CF, art. 5º, XLVII","tags":["constituição"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Disposições constitucionais aplicáveis ao direito penal"]]},{"termo":"Progressão no crime hediondo","extenso":"Regime dos hediondos","pratica":"Os condenados por crime hediondo progridem de regime com percentuais maiores de cumprimento da pena.","tecnica":"Desde o Pacote Anticrime (Lei 13.964/2019), os percentuais estão na LEP, art. 112: 40% (primário), 50% (com morte, primário) e 60% (reincidente específico), entre outros.","dispositivo":"LEP, art. 112","tags":["hediondos"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Crimes hediondos (Lei 8.072/1990)"]]},{"termo":"Medidas socioeducativas","extenso":"Respostas ao ato infracional","pratica":"Medidas aplicadas ao adolescente que pratica ato infracional: advertência, reparação do dano, serviços à comunidade, liberdade assistida, semiliberdade e internação.","tecnica":"ECA, art. 112. A internação dura no máximo 3 anos e é liberada compulsoriamente aos 21 anos.","dispositivo":"ECA, arts. 112 e 121","tags":["ECA"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Estatuto da Criança e do Adolescente"]]},{"termo":"Elemento subjetivo do abuso de autoridade","extenso":"Finalidade específica","pratica":"Só há crime de abuso de autoridade se o agente agir para prejudicar alguém, beneficiar a si ou a terceiro, ou por capricho ou satisfação pessoal.","tecnica":"Lei 13.869/2019, art. 1º, § 1º. A divergência na interpretação da lei ou na avaliação de fatos e provas não configura abuso (§ 2º).","dispositivo":"Lei 13.869/2019, art. 1º","tags":["abuso de autoridade"],"materias":["Noções de Direito Penal"],"topicos":[["Noções de Direito Penal","Abuso de autoridade (Lei 13.869/2019)"]]},{"termo":"Sistema acusatório","extenso":"Separação entre acusar e julgar","pratica":"Quem acusa (MP) não julga; o juiz é imparcial e não substitui a atuação probatória do órgão de acusação.","tecnica":"CPP, art. 3º-A (Pacote Anticrime). Juiz das garantias: controla a legalidade da investigação.","dispositivo":"CPP, art. 3º-A","tags":["princípios"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições preliminares do CPP"]]},{"termo":"Juiz das garantias","extenso":"Juiz da fase de investigação","pratica":"Juiz responsável pelo controle da legalidade da investigação e pelos direitos do investigado.","tecnica":"CPP, art. 3º-B. O STF declarou a constitucionalidade (ADIs 6298 e outras) com ajustes: sua competência cessa com o oferecimento da denúncia.","dispositivo":"CPP, art. 3º-B","tags":["juiz das garantias"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições preliminares do CPP"],["Noções de Direito Processual Penal","Inquérito policial"]]},{"termo":"Indiciamento","extenso":"Apontamento formal do suspeito","pratica":"Ato do delegado que aponta, de forma fundamentada, o investigado como provável autor do crime.","tecnica":"Ato privativo do delegado (Lei 12.830/2013, art. 2º, § 6º). Diferente da indiciação no PAD.","dispositivo":null,"tags":["inquérito"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Inquérito policial"]]},{"termo":"Arquivamento do inquérito","extenso":"Encerramento da investigação","pratica":"Quando não há base para denunciar, o MP decide arquivar o inquérito e comunica a decisão à vítima, ao investigado e à autoridade policial.","tecnica":"CPP, art. 28 (Lei 13.964/2019), conforme o STF (ADI 6298 e outras): o MP também submete o arquivamento ao juiz, que pode provocar a revisão se houver ilegalidade; a vítima pode pedir a revisão em 30 dias. A autoridade policial não pode mandar arquivar autos de inquérito (art. 17).","dispositivo":"CPP, arts. 17 e 28","tags":["inquérito"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Inquérito policial"]]},{"termo":"Princípio da obrigatoriedade","extenso":"Ação penal pública","pratica":"Havendo justa causa, o MP é obrigado a oferecer denúncia.","tecnica":"Mitigado pela transação penal e pelo acordo de não persecução penal (ANPP). Na ação privada vigora a oportunidade.","dispositivo":null,"tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Indisponibilidade da ação penal","extenso":"MP não desiste","pratica":"O MP não pode desistir da ação penal pública já proposta, nem do recurso interposto.","tecnica":"CPP, arts. 42 e 576. Na ação privada, o querelante pode desistir (perdão, perempção).","dispositivo":"CPP, arts. 42 e 576","tags":["ação penal"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"ANPP","extenso":"Acordo de não persecução penal","pratica":"Acordo entre MP e investigado para evitar o processo em crimes sem violência ou grave ameaça com pena mínima inferior a 4 anos.","tecnica":"CPP, art. 28-A. Exige confissão formal e circunstanciada. Não cabe em violência doméstica, para reincidentes ou se cabível transação penal.","dispositivo":"CPP, art. 28-A","tags":["acordos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Decadência do direito de queixa","extenso":"Prazo de 6 meses","pratica":"O ofendido tem 6 meses, contados do dia em que soube quem é o autor do crime, para oferecer queixa ou representação.","tecnica":"CPP, art. 38. Prazo penal (inclui o dia do começo) e fatal: não se suspende nem se interrompe.","dispositivo":"CPP, art. 38","tags":["ação penal","prazos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Ação penal"]]},{"termo":"Defensor dativo","extenso":"Defensor nomeado pelo juiz","pratica":"Advogado nomeado pelo juiz quando o acusado não tem defensor.","tecnica":"CPP, art. 263. Nenhum acusado será processado ou julgado sem defensor (art. 261). O acusado pode, a todo tempo, nomear outro de sua confiança.","dispositivo":"CPP, arts. 261 e 263","tags":["defesa"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Juiz, Ministério Público, acusado e defensor"]]},{"termo":"Impedimento do juiz (CPP)","extenso":"Proibição objetiva de atuar","pratica":"O juiz não pode atuar quando ele, cônjuge ou parente já atuou no processo ou tem interesse direto.","tecnica":"CPP, art. 252. Suspeição (art. 254): amizade íntima, inimizade capital, aconselhamento da parte etc.","dispositivo":"CPP, arts. 252 e 254","tags":["imparcialidade"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Juiz, Ministério Público, acusado e defensor"]]},{"termo":"Assistente de acusação","extenso":"Vítima atuando ao lado do MP","pratica":"O ofendido ou seu representante pode intervir na ação pública como assistente do MP.","tecnica":"CPP, art. 268. Admitido depois do recebimento da denúncia e enquanto não passar em julgado a sentença. O corréu no mesmo processo não pode ser assistente (art. 270).","dispositivo":"CPP, arts. 268 a 273","tags":["sujeitos"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Assistentes, auxiliares da justiça, peritos e intérpretes"]]},{"termo":"Perito oficial","extenso":"Auxiliar da justiça penal","pratica":"Exame de corpo de delito e outras perícias são feitos por perito oficial com diploma de nível superior.","tecnica":"CPP, art. 159. Na falta, por 2 pessoas idôneas com diploma superior. As partes podem indicar assistente técnico.","dispositivo":"CPP, art. 159","tags":["perícia"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Assistentes, auxiliares da justiça, peritos e intérpretes"]]},{"termo":"Citação por edital (CPP)","extenso":"Citação do réu não encontrado","pratica":"Quando o réu não é encontrado, é citado por edital com prazo de 15 dias.","tecnica":"CPP, art. 366: se não comparecer nem constituir advogado, ficam suspensos o processo e a prescrição. Súmula 415 do STJ limita a suspensão da prescrição ao prazo máximo da pena.","dispositivo":"CPP, arts. 361 e 366","tags":["citação"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Citações e intimações"]]},{"termo":"Citação por hora certa (CPP)","extenso":"Citação do réu que se oculta","pratica":"Se o réu se esconde para não ser citado, o oficial faz a citação com hora certa.","tecnica":"CPP, art. 362, seguindo o CPC. Se o réu não comparecer, recebe defensor dativo e o processo segue.","dispositivo":"CPP, art. 362","tags":["citação"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Citações e intimações"]]},{"termo":"Resposta à acusação","extenso":"Defesa escrita","pratica":"Depois de citado, o acusado apresenta resposta escrita em 10 dias, com documentos, provas e até 8 testemunhas.","tecnica":"CPP, arts. 396 e 396-A, no rito ordinário. Se não apresentar, o juiz nomeia defensor.","dispositivo":"CPP, art. 396-A","tags":["procedimento"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Processo comum e instrução criminal"]]},{"termo":"Rito ordinário","extenso":"Procedimento comum ordinário","pratica":"Usado para crimes com pena máxima igual ou superior a 4 anos.","tecnica":"CPP, art. 394. Sumário: pena máxima inferior a 4 anos. Sumaríssimo: infrações de menor potencial ofensivo (Lei 9.099). Prazo da audiência no ordinário: até 60 dias.","dispositivo":"CPP, art. 394","tags":["procedimento"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Processo comum e instrução criminal"]]},{"termo":"Sorteio dos jurados","extenso":"Formação da lista da sessão","pratica":"Para cada sessão de julgamento, sorteiam-se 25 jurados entre os alistados.","tecnica":"CPP, art. 433. A sessão se instala com pelo menos 15 jurados presentes; desses, 7 formam o Conselho de Sentença.","dispositivo":"CPP, arts. 433 e 463","tags":["júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: sorteio, convocação e função do jurado"]]},{"termo":"Função do jurado","extenso":"Serviço obrigatório","pratica":"O serviço do júri é obrigatório para cidadãos maiores de 18 anos de notória idoneidade.","tecnica":"CPP, arts. 436 e 437. Constitui serviço público relevante, presume idoneidade moral e dá preferência em licitações e concursos (art. 440).","dispositivo":"CPP, arts. 436 a 446","tags":["júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: sorteio, convocação e função do jurado"]]},{"termo":"Recusa peremptória","extenso":"Recusa imotivada de jurado","pratica":"Defesa e acusação podem recusar até 3 jurados cada, sem justificar.","tecnica":"CPP, art. 468. Recusas motivadas (impedimento, suspeição) não têm limite.","dispositivo":"CPP, art. 468","tags":["júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: composição, Conselho de Sentença, sessões e instrução em plenário"]]},{"termo":"Votação dos quesitos","extenso":"Votação secreta na sala especial","pratica":"Os jurados respondem aos quesitos com cédulas SIM e NÃO, em sala especial.","tecnica":"Encerra-se a votação ao atingir mais de 3 votos no mesmo sentido (CPP, art. 483, § 1º e § 2º), preservando o sigilo.","dispositivo":"CPP, arts. 483 e 485","tags":["júri"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Júri: debates, quesitos e votação, sentença, ata e atribuições do presidente"]]},{"termo":"Relaxamento da prisão","extenso":"Prisão ilegal","pratica":"Prisão ilegal deve ser imediatamente relaxada pelo juiz.","tecnica":"CF, art. 5º, LXV. Diferente da liberdade provisória, que se aplica à prisão legal quando não cabe preventiva.","dispositivo":"CF, art. 5º, LXV","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Medidas cautelares diversas da prisão","extenso":"Alternativas à prisão","pratica":"Comparecimento periódico, proibição de frequentar lugares, de contato, de ausentar-se, recolhimento noturno, suspensão de função, fiança, monitoração eletrônica.","tecnica":"CPP, art. 319. A preventiva só cabe quando elas não bastarem (art. 282, § 6º).","dispositivo":"CPP, art. 319","tags":["cautelares"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Revisão da preventiva","extenso":"Reavaliação a cada 90 dias","pratica":"O juiz que decretou a preventiva deve revisar a necessidade a cada 90 dias, de ofício.","tecnica":"CPP, art. 316, parágrafo único. O STF entende que a falta de revisão não gera soltura automática.","dispositivo":"CPP, art. 316","tags":["prisão"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Prisão e liberdade provisória"]]},{"termo":"Habeas corpus de ofício","extenso":"Concessão sem pedido","pratica":"Juízes e tribunais podem conceder HC de ofício quando verificarem coação ilegal.","tecnica":"CPP, art. 654, § 2º. O HC pode ser impetrado por qualquer pessoa, sem advogado, inclusive em favor de terceiro.","dispositivo":"CPP, art. 654","tags":["HC"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Habeas corpus e seu processo"]]},{"termo":"Presunção de inocência","extenso":"Estado de inocência","pratica":"Ninguém é considerado culpado até o trânsito em julgado da sentença condenatória.","tecnica":"CF, art. 5º, LVII. O STF (ADCs 43, 44 e 54) vedou a execução provisória da pena antes do trânsito.","dispositivo":"CF, art. 5º, LVII","tags":["princípios"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições constitucionais aplicáveis ao processo penal"]]},{"termo":"Provas ilícitas","extenso":"Prova obtida com violação de direitos","pratica":"São inadmissíveis no processo as provas obtidas por meios ilícitos.","tecnica":"CF, art. 5º, LVI; CPP, art. 157: também as derivadas (frutos da árvore envenenada), salvo fonte independente ou descoberta inevitável.","dispositivo":"CPP, art. 157","tags":["provas"],"materias":["Noções de Direito Processual Penal"],"topicos":[["Noções de Direito Processual Penal","Disposições constitucionais aplicáveis ao processo penal"]]}]$termos$::jsonb;
  pares jsonb := $pares$[["Sujeito oculto","Sujeito indeterminado"],["Complemento nominal","Adjunto adnominal"],["Conjunção conclusiva","Conjunção explicativa"],["Metáfora","Metonímia"],["Pressuposto","Inferência"],["Hiperônimo","Sinonímia"],["Texto narrativo","Texto descritivo"],["Frase nominal","Frase, oração e período"],["Aposto","Vocativo"],["Parassíntese","Derivação"],["Câmara","Turma"],["Turma","Turma Recursal"],["Comissão permanente","Comissão temporária"],["Preparo","Deserção"],["IRDR","IAC"],["Súmula","Súmula vinculante"],["Juizado Especial Cível","Juizado Especial da Fazenda Pública"],["Vitaliciedade","Estabilidade do servidor"],["Vitaliciedade","Inamovibilidade"],["Distribuição","Distribuição por dependência"],["Clima organizacional","Cultura organizacional"],["Recrutamento","Seleção de pessoas"],["Teoria da expectativa","Teoria da equidade"],["Rotatividade","Absenteísmo"],["Mudança incremental","Inovação"],["Efeito de leniência","Efeito halo"],["Escala gráfica","Incidentes críticos"],["Despesa corrente","Despesa de capital"],["Restos a pagar processados","Despesas de exercícios anteriores"],["Concorrência","Pregão"],["Licitação deserta","Dispensa de licitação"],["Governança pública","Accountability"],["Economicidade","Eficiência"],["Constituição promulgada","Constituição rígida"],["Direitos sociais","Direitos da personalidade"],["Perda da nacionalidade","Brasileiro naturalizado"],["Cargo em comissão","Estabilidade do servidor"],["Garantias do Judiciário","Garantias da magistratura"],["Agente político","Particular em colaboração"],["Reintegração","Recondução"],["Reversão","Aproveitamento"],["Poder vinculado","Poder discricionário"],["Cassação do ato","Revogação"],["Controle interno","Controle legislativo"],["Supremacia do interesse público","Indisponibilidade do interesse público"],["Teoria do risco administrativo","Omissão do Estado"],["Tomada de preços","Concorrência"],["Erro","Coação"],["Lesão","Fraude contra credores"],["Simulação","Erro"],["Condição","Planos do negócio jurídico"],["Interrupção da prescrição","Causas impeditivas da prescrição"],["Benfeitorias","Pertenças"],["Abuso de direito","Ato lícito"],["Interesse processual","Legitimidade"],["Capacidade processual","Capacidade postulatória"],["Litispendência","Coisa julgada material"],["Nulidade relativa","Nulidade"],["Indeferimento da petição inicial","Improcedência liminar do pedido"],["Saneamento","Julgamento antecipado do mérito"],["Litigância de má-fé","Ato atentatório à dignidade da justiça"],["Princípio da especialidade","Princípio da consunção"],["Princípio da subsidiariedade","Princípio da especialidade"],["Crime doloso","Crime culposo"],["Tentativa","Crime impossível"],["Apropriação indébita","Furto"],["Extorsão","Roubo"],["Resistência","Desacato"],["Peculato culposo","Peculato"],["Excesso de exação","Concussão"],["Contagem de prazo penal","Prazos em dias úteis"],["Juiz das garantias","Sistema acusatório"],["Indiciamento","Indiciação"],["Princípio da obrigatoriedade","Indisponibilidade da ação penal"],["ANPP","ANPC"],["Relaxamento da prisão","Fiança"],["Citação por edital (CPP)","Citação por edital"],["Impedimento do juiz (CPP)","Suspeição"],["Probidade","Moralidade administrativa"],["Afastamento preventivo","Suspensão"],["Prazo do PAD","Prescrição disciplinar"]]$pares$::jsonb;
  t jsonb;
  p jsonb;
  a uuid;
  b uuid;
  ids_materias uuid[];
  ids_topicos uuid[];
begin
  if uid is null then
    raise exception 'É preciso estar logada para preparar a nomenclatura.';
  end if;

  insert into public.configuracoes (user_id) values (uid) on conflict (user_id) do nothing;
  if (select termos_2022_b from public.configuracoes where user_id = uid) then
    return;
  end if;

  for t in select * from jsonb_array_elements(termos) loop
    if exists (select 1 from public.termos where user_id = uid and lower(termo) = lower(t ->> 'termo')) then
      continue;
    end if;
    select coalesce(array_agg(id), '{}') into ids_materias from public.materias
    where user_id = uid and nome in (select jsonb_array_elements_text(t -> 'materias'));
    select coalesce(array_agg(tp.id), '{}') into ids_topicos
    from public.topicos tp
    join public.materias mt on mt.id = tp.materia_id
    where tp.user_id = uid
      and exists (
        select 1 from jsonb_array_elements(t -> 'topicos') par
        where par ->> 0 = mt.nome and par ->> 1 = tp.nome
      );
    insert into public.termos (user_id, termo, extenso, pratica, tecnica, dispositivo, tags, materia_ids, topico_ids)
    values (
      uid, t ->> 'termo', t ->> 'extenso', t ->> 'pratica', t ->> 'tecnica', t ->> 'dispositivo',
      array(select jsonb_array_elements_text(t -> 'tags')), ids_materias, ids_topicos
    );
  end loop;

  -- "Não confundir com", nas duas direções.
  for p in select * from jsonb_array_elements(pares) loop
    select id into a from public.termos where user_id = uid and lower(termo) = lower(p ->> 0) limit 1;
    select id into b from public.termos where user_id = uid and lower(termo) = lower(p ->> 1) limit 1;
    if a is not null and b is not null and a <> b then
      insert into public.termos_relacionados (user_id, termo_id, relacionado_id)
      values (uid, a, b), (uid, b, a)
      on conflict do nothing;
    end if;
  end loop;

  update public.configuracoes set termos_2022_b = true where user_id = uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- Uma chamada só, na ordem certa. O app chama esta função ao abrir.
-- ---------------------------------------------------------------------------

create or replace function public.preparar_caderno()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  perform public.semear_edital();
  perform public.atualizar_edital_2022();
  perform public.revisar_edital_2022();
  perform public.semear_termos();
  perform public.semear_termos_2022();
  perform public.semear_termos_2022b();
end;
$$;

revoke execute on function public.edital_tjdft_2022() from public, anon;
revoke execute on function public.revisar_edital_2022() from public, anon;
revoke execute on function public.semear_termos_2022b() from public, anon;
revoke execute on function public.preparar_caderno() from public, anon;
grant execute on function public.edital_tjdft_2022() to authenticated;
grant execute on function public.revisar_edital_2022() to authenticated;
grant execute on function public.semear_termos_2022b() to authenticated;
grant execute on function public.preparar_caderno() to authenticated;
